window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[83]={"id":"083","numero":83,"titre":"Infections et inflammations oculaires","objectifs":[{"id":"83-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique","contenu":"<p>Le diagnostic d'une infection ou inflammation oculaire repose sur trois questions pivots — <strong>douleur</strong>, <strong>BAV</strong> (baisse d'acuité visuelle), <strong>rougeur et sécrétions</strong> — qui orientent immédiatement vers l'une des grandes entités sémiologiques.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>À recueillir / rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              <strong>Mode d’installation :</strong> <span class=\"kw-clinique\">brutal</span> (paraphimosis ophtalmo, plaie de cornée), <span class=\"kw-clinique\">rapide</span> (conjonctivite, kératite, uvéite, endophtalmie), <span class=\"kw-clinique\">progressif</span> (sécheresse, sclérite récidivante)<br>\n              <strong>Latéralité :</strong> unilatéral, bilatéral, à bascule (uvéite SpA <span class=\"kw-bio\">HLA-B27</span>+)<br>\n              <strong>Douleur :</strong> superficielle « grains de sable » (conjonctivite) ; profonde, ciliaire, insomniante (sclérite, uvéite) ; intense + photophobie + blépharospasme (kératite, <span class=\"kw-clinique\">abcès</span> cornée)<br>\n              <strong>BAV :</strong> absente (conjonctivite, hémorragie sous-conjonctivale, épisclérite) ; transitoire (sécrétions devant l'axe optique) ; permanente (kératite centrale, uvéite, endophtalmie)<br>\n              <strong>Sécrétions :</strong> mucopurulentes en « poils de pinceau » (<span class=\"kw-etio\">bactérienne</span>) ; claires (virale, <span class=\"kw-etio\">allergique</span>) ; absentes (uvéite, sclérite)<br>\n              <strong><span class=\"kw-def\">Terrain</span> :</strong> port de <span class=\"kw-clinique\">lentilles de contact</span> (kératite à pyocyanique, amibienne) ; <span class=\"kw-clinique\">ATCD herpès oculaire</span> ; <span class=\"kw-clinique\">immunodépression</span> ; <span class=\"kw-ttt\">chirurgie</span> oculaire récente (endophtalmie) ; <span class=\"kw-ttt\">corticothérapie</span> prolongée ; contexte épidémique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>\n              <strong>Acuité visuelle :</strong> mesurée œil par œil, de loin et de près<br>\n              <strong>Inspection externe :</strong> paupières (<span class=\"kw-clinique\">œdème</span>, vésicules <span class=\"kw-etio\">HSV</span>/VZV, ectropion, <span class=\"kw-clinique\">eczéma</span> <span class=\"kw-etio\">atopique</span>), conjonctive (hyperhémie diffuse <span class=\"kw-bio\">vs</span> cul-de-sac inférieur, chémosis, hémorragie)<br>\n              <strong>Sécrétions :</strong> aspect, quantité, latéralité, <span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-clinique\">prétragienne</span> sensible (signe la cause infectieuse <span class=\"kw-etio\">virale</span>/<span class=\"kw-clinique\">Chlamydia</span>)<br>\n              <strong>Lampe à fente (LAF) :</strong> cornée (transparence, <span class=\"kw-clinique\">ulcération</span>), chambre antérieure (Tyndall, hypopion, précipités rétro-cornéens), pupille (myosis relatif d'uvéite, synéchies postérieures), iris (atrophie sectorielle)<br>\n              <strong>Test à la fluorescéine :</strong> systématique devant toute kératalgie — ulcère dendritique = HSV, ponctuée superficielle = sécheresse/<span class=\"kw-etio\">adénovirus</span>, signe de Seidel = plaie cornéenne<br>\n              <strong>Fond d’œil (<span class=\"kw-imagerie\">FO</span>) :</strong> systématique si suspicion d'uvéite ou endophtalmie (hyalite, foyer choriorétinien, papillite)<br>\n              <strong>Tonus oculaire :</strong> au tonomètre — hypertonie évoque uvéite herpétique, Posner-Schlossman, glaucome aigu par fermeture de l'angle (DD)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes négatifs à documenter</strong></td>\n            <td>Absence de douleur intense profonde, absence de BAV persistante (oriente vers conjonctivite/épisclérite <span class=\"kw-bio\">vs</span> kératite/uvéite) ; transparence cornéenne (signe sa conservation, par opposition aux <span class=\"kw-clinique\">abcès</span>) ; profondeur de chambre antérieure normale (élimine glaucome aigu par fermeture)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Triade pivot.</strong> Œil rouge <span class=\"kw-clinique\">+ douleur + BAV</span> = <span class=\"kw-alerte\">urgence</span> ophtalmologique (kératite, uvéite, endophtalmie, glaucome aigu). Œil rouge <span class=\"kw-clinique\">isolé sans douleur ni BAV</span> = conjonctivite, hémorragie sous-conjonctivale, épisclérite (rang A, ambulatoire). Toute association d'une de ces 3 entités à la composante « infection/inflammation » impose la LAF.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision · 81 — Altération chronique de la vision</em></p>","frequence":3},{"id":"83-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir devant un œil rouge douloureux sans baisse d’acuité visuelle","contenu":"<p>Œil rouge + douleur + <strong>AV conservée</strong> = situation moins urgente que l'œil rouge avec BAV, mais l'orientation diagnostique dépend de la <span class=\"kw-clinique\">latéralité</span>, des <span class=\"kw-clinique\">sécrétions</span> et de la <span class=\"kw-clinique\">topographie</span> de la rougeur.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Clinique discriminante</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Conjonctivite <span class=\"kw-etio\">bactérienne</span> aiguë</strong></td>\n            <td>Hyperhémie diffuse prédominant en <span class=\"kw-clinique\">cul-de-sac inférieur</span> ; sécrétions <span class=\"kw-clinique\">mucopurulentes</span> en « poils de pinceau » au réveil ; uni- puis bilatérale</td>\n            <td><span class=\"kw-ttt\">Lavages au sérum physiologique</span> ; <span class=\"kw-ttt\">collyre antiseptique</span> 4–6×/j ; <span class=\"kw-ttt\">ATB</span> ciblés CG+ uniquement si <span class=\"kw-alerte\">signe de gravité</span> ou résistance — <span class=\"kw-clinique\">hygiène des mains</span> systématique</td>\n          </tr>\n          <tr>\n            <td><strong>Conjonctivite <span class=\"kw-etio\">virale</span> (<span class=\"kw-etio\">adénovirus</span>)</strong></td>\n            <td>Hyperhémie + <span class=\"kw-clinique\">hémorragies conjonctivales</span> ; sécrétions <span class=\"kw-clinique\">claires</span> ; <span class=\"kw-clinique\">adénopathie prétragienne</span> sensible ; contexte épidémique</td>\n            <td>Traitement symptomatique (lavages, mouillants) ; <span class=\"kw-ttt\">CTC locaux seulement si forme sévère</span> avec membranes (<span class=\"kw-clinique\">les</span> CTC prolongent le portage <span class=\"kw-etio\">viral</span>) ; éviction scolaire/professionnelle</td>\n          </tr>\n          <tr>\n            <td><strong>Conjonctivite <span class=\"kw-etio\">allergique</span></strong></td>\n            <td><span class=\"kw-clinique\">Prurit intense</span> ; bilatérale ; chémosis blanc laiteux ; rhinite associée ; saisonnier ou per-annuel</td>\n            <td><span class=\"kw-ttt\">Anti-H1 PO</span> de 2ᵉ génération ; <span class=\"kw-ttt\">collyre anti-H1</span> et/ou <span class=\"kw-ttt\">antidégranulant mastocytaire (cromone)</span> ; <span class=\"kw-ttt\">CTC en cure courte</span> si intense ; éviction + bilan allergo</td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie sous-conjonctivale</strong></td>\n            <td>Nappe rouge vif <span class=\"kw-clinique\">indolore</span> ; spontanée ou post-traumatique ; AV conservée</td>\n            <td>Aucun traitement spécifique ; rechercher <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">anticoagulants</span>, trouble de l'hémostase, traumatisme</td>\n          </tr>\n          <tr>\n            <td><strong>Épisclérite</strong></td>\n            <td>Rougeur en <span class=\"kw-clinique\">secteur</span>, modérément douloureuse ; <span class=\"kw-clinique\">disparaît à l'instillation d'un vasoconstricteur</span> (phényléphrine) ; pas de BAV</td>\n            <td>Souvent idiopathique ; <span class=\"kw-ttt\">AINS</span> locaux ou CTC locaux ; <strong>pas de bilan</strong> au 1ᵉʳ épisode (bilan sclérite si récidive)</td>\n          </tr>\n          <tr>\n            <td><strong>Sclérite</strong></td>\n            <td>Douleur <span class=\"kw-clinique\">ciliaire intense insomniante</span>, aggravée par la mobilisation ; rougeur plane/nodulaire ; <span class=\"kw-clinique\">ne disparaît pas</span> au vasoconstricteur ❌</td>\n            <td><span class=\"kw-ttt\">Bilan étiologique dès le 1ᵉʳ épisode</span> (consultation médecine interne) ; <span class=\"kw-ttt\">AINS</span> PO en 1ʳᵉ intention ; CTC ou <span class=\"kw-ttt\">immunosuppresseurs</span> si forme grave (<span class=\"kw-clinique\">nécrose</span> sclérale, BAV)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège QCM.</strong> Le <span class=\"kw-clinique\">vasoconstricteur (chlorhydrate de phényléphrine, néosynéphrine)</span> distingue épisclérite (rougeur disparaît) de sclérite (rougeur persiste). C'est le test discriminant clé au lit du patient.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":2},{"id":"83-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une hémorragie sous conjonctivale","contenu":"<p>L'hémorragie sous-conjonctivale est une <span class=\"kw-def\">extravasation sanguine</span> dans l'espace sous-conjonctival, presque toujours <strong>bénigne</strong> chez l'adulte sain mais nécessite une enquête étiologique systématique.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Présentation</strong></td>\n            <td>Nappe ou plage <span class=\"kw-clinique\">rouge vif homogène</span> sous la conjonctive bulbaire, le plus souvent unilatérale ; bords nets ; <span class=\"kw-clinique\">absence de douleur</span>, <span class=\"kw-clinique\">absence de BAV</span>, <span class=\"kw-clinique\">absence de sécrétions</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic positif</span></strong></td>\n            <td>Purement <span class=\"kw-clinique\">clinique</span> à l'inspection ; aucun examen complémentaire requis pour confirmer le diagnostic</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>Résorption spontanée en <span class=\"kw-chiffre\">10 à 15 jours</span>, passant par <span class=\"kw-clinique\">les</span> classiques variations chromatiques (rouge vif → violet → jaune) ; aucun traitement local n'accélère la résorption</td>\n          </tr>\n          <tr>\n            <td><strong>Enquête étiologique</strong></td>\n            <td>\n              <strong>Idiopathique :</strong> cause la plus fréquente (effort à glotte fermée — <span class=\"kw-clinique\">toux</span>, éternuement, <span class=\"kw-clinique\">vomissement</span>, Valsalva)<br>\n              <strong>Traumatique :</strong> traumatisme oculaire ou crânien (éliminer une plaie occulte, un corps étranger intra-oculaire)<br>\n              <strong><span class=\"kw-def\">HTA</span></strong> ⭐ : à dépister systématiquement, surtout si récidive<br>\n              <strong><span class=\"kw-ttt\">Anticoagulants</span> / anti-agrégants :</strong> <span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">AOD</span>, <span class=\"kw-ttt\">héparine</span>, <span class=\"kw-ttt\">aspirine</span> — vérifier l'<span class=\"kw-bio\">INR</span>/ratios<br>\n              <strong>Troubles de l’hémostase :</strong> thrombopénie, hémopathie, déficit en facteurs de coagulation\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Drapeaux rouges</span></strong></td>\n            <td><span class=\"kw-alerte\">Récidives</span> sans facteur favorisant → bilan d'hémostase + bilan vasculaire ; <span class=\"kw-alerte\">contexte traumatique</span> → exploration ophtalmologique complète à la recherche d'une plaie pénétrante</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Diagnostic <span class=\"kw-clinique\">visuel pur</span>, <span class=\"kw-def\">pronostic</span> excellent, aucun traitement étiologique local. La seule action utile est l'enquête sur <span class=\"kw-def\">HTA</span>, <span class=\"kw-ttt\">anticoagulation</span> et trouble de l'hémostase si <span class=\"kw-def\">terrain</span> évocateur ou récidive.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":0},{"id":"83-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une conjonctivite","contenu":"<p>La conjonctivite est une <span class=\"kw-def\">inflammation de la conjonctive</span> donnant le tableau pivot <strong>œil rouge douloureux SANS BAV</strong> (hors gêne transitoire par sécrétions). La démarche distingue <span class=\"kw-clinique\">les</span> formes <span class=\"kw-clinique\">infectieuses</span> (<span class=\"kw-etio\">bactérienne</span>, virale, chronique à <span class=\"kw-clinique\">Chlamydia</span>) des formes <span class=\"kw-clinique\">allergiques</span> (saisonnière, vernale, <span class=\"kw-etio\">atopique</span>, <span class=\"kw-def\">contact</span>) et de la <span class=\"kw-clinique\">sécheresse oculaire</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Signe</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Œil rouge</strong></td>\n            <td><span class=\"kw-clinique\">Hyperhémie conjonctivale diffuse</span>, sans cercle périkératique (qui orienterait vers une atteinte intra-oculaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Douleur</strong></td>\n            <td>Superficielle : sensation de <span class=\"kw-clinique\">corps étranger</span>, <span class=\"kw-clinique\">grains de sable</span>, <span class=\"kw-clinique\">brûlure</span>, <span class=\"kw-clinique\">prurit</span></td>\n          </tr>\n          <tr>\n            <td><strong>BAV</strong></td>\n            <td>\n              <strong>Gêne visuelle transitoire</strong> par sécrétions devant l'axe optique, améliorée par le clignement ou le lavage<br>\n              <strong>BAV permanente + douleur</strong> ⚠️ = atteinte cornéenne associée (kérato-conjonctivite) → sortir du cadre de la conjonctivite simple\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes</strong></td>\n            <td>Infectieuses (<span class=\"kw-etio\">bactérienne</span> aiguë/chronique, virale), inflammatoires/allergiques, sécheresse</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Formes infectieuses</h4>\n      <table >\n        <thead>\n          <tr><th></th><th><span class=\"kw-etio\">Bactérienne</span> aiguë</th><th><span class=\"kw-etio\">Virale</span> (<span class=\"kw-etio\">adénovirus</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Germes</strong></td>\n            <td><span class=\"kw-bio\">CG+</span> (<span class=\"kw-etio\">streptocoque</span>, staphylocoque)</td>\n            <td><span class=\"kw-bio\">Adénovirus</span> — épidémies, <span class=\"kw-alerte\">extrêmement contagieux</span></td>\n          </tr>\n          <tr>\n            <td><strong>Latéralité</strong></td>\n            <td>Uni- ou bilatérale, avec intervalle libre possible</td>\n            <td>Unilatérale initialement, bilatéralisation par auto-contamination</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <strong>Rougeur :</strong> diffuse, prédomine en cul-de-sac inférieur<br>\n              <strong>Sécrétions :</strong> <span class=\"kw-clinique\">mucopurulentes</span> en « poils de pinceau » au réveil<br>\n              <strong>Chémosis</strong> et <span class=\"kw-clinique\">œdème</span> palpébral si sévère\n            </td>\n            <td>\n              <strong>Hyperhémie</strong> franche + <span class=\"kw-clinique\">hémorragies conjonctivales</span><br>\n              <strong>Sécrétions :</strong> <span class=\"kw-clinique\">claires</span><br>\n              <strong><span class=\"kw-clinique\">Adénopathie</span> prétragienne</strong> sensible (signe la cause infectieuse) ⭐\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prélèvement</strong></td>\n            <td>Conjonctival par écouvillonnage <span class=\"kw-chiffre\">si forme grave ou résistante au TTT de 1ʳᵉ ligne</span></td>\n            <td>Test diagnostique rapide sur échantillon lacrymal <span class=\"kw-chiffre\">si doute avec une bactérienne</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>Guérison habituelle sans séquelle ; si chronique ou récidivant → rechercher <span class=\"kw-clinique\">trouble de perméabilité des voies lacrymales</span> (surtout âges extrêmes, caractère unilatéral)</td>\n            <td>Spontanément favorable en <span class=\"kw-chiffre\">10–15 jours</span> ; complications : <span class=\"kw-alerte\">membranes fibrineuses</span>, <span class=\"kw-alerte\">kératoconjonctivite</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conjonctivites bactériennes chroniques</h4>\n      <ul>\n        <li><strong>Conjonctivite à inclusion :</strong> <span class=\"kw-bio\">Chlamydia trachomatis</span> — <span class=\"kw-clinique\">IST</span> adulte, uni/bilatérale, associée à urétrite/vaginite ; TTT : <span class=\"kw-ttt\">azithromycine PO en monodose</span></li>\n        <li><strong>Trachome :</strong> <span class=\"kw-bio\">Chlamydia trachomatis</span> — pays à faibles ressources, conjonctivite bilatérale, follicules, fibrose tarsale, entropion ; <span class=\"kw-alerte\">2ᵉ cause mondiale de cécité évitable</span> après la cataracte ; TTT : <span class=\"kw-ttt\">azithromycine</span> ou tétracyclines + <span class=\"kw-ttt\">chirurgie</span> palpébrale</li>\n        <li><strong>Syndrome oculo-glandulaire de Parinaud :</strong> forme ophtalmique de la maladie des griffes du chat (Bartonella henselae,<span class=\"kw-chiffre\"> 10 %</span>), enfant — conjonctivite + <span class=\"kw-clinique\">adénopathie</span> prétragienne</li>\n      </ul>\n\n      <h4>Formes allergiques</h4>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Présentation</th><th>Traitement</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Saisonnière / per-annuelle</strong></td><td>bilatérale, <span class=\"kw-clinique\">prurit intense</span>, chémosis blanc laiteux, rhinite associée</td><td>anti-<span class=\"kw-chiffre\">H1</span> PO + collyre antihistaminique ou antidégranulant mastocytaire (<span class=\"kw-ttt\">cromone</span> ⭐ tombé en annale) ; CTC en cure courte si intense</td></tr>\n          <tr><td><strong>Kérato-conjonctivite vernale (printanière)</strong></td><td><span class=\"kw-clinique\">garçons avant la puberté</span> (&lt;<span class=\"kw-chiffre\"> 10 ans</span>), printemps/été, <span class=\"kw-clinique\">prurit</span> + photophobie + blépharospasme ; formes limbique (grains de Trantas) ou tarsale (papilles géantes, kératite)</td><td>CTC topiques en aigu, <span class=\"kw-ttt\">ciclosporine collyre</span> en fond</td></tr>\n          <tr><td><strong>Kérato-conjonctivite <span class=\"kw-etio\">atopique</span></strong></td><td>homme adulte, <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-etio\">atopique</span> ; <span class=\"kw-clinique\">eczéma</span> palpébral, ectropion ; complications : kératocône, cataracte en écusson, glaucome cortico-induit</td><td>CTC + <span class=\"kw-ttt\">immunosuppresseurs</span> locaux (<span class=\"kw-ttt\">tacrolimus</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Allergie</span> de <span class=\"kw-def\">contact</span></strong></td><td><span class=\"kw-ci\">hypersensibilité</span> retardée à un allergène appliqué (collyres ATB/mydriatiques/antiglaucomateux, cosmétique, professionnel)</td><td>éviction + CTC locaux si intense</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pivot étiologique.</strong> Une conjonctivite chronique unilatérale au-delà de <span class=\"kw-chiffre\">4 semaines</span> impose la recherche d'un <span class=\"kw-clinique\">trouble de perméabilité lacrymale</span> (sténose canaliculaire, dacryocystite) ou d'une <span class=\"kw-clinique\">cause mécanique</span> (CE, trichiasis, lagophtalmie).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span> · 168 — Herpesvirus · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":1},{"id":"83-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une épisclérite, une sclérite","contenu":"<p>Épisclérite et sclérite réalisent toutes deux un œil rouge <span class=\"kw-clinique\">souvent sans BAV</span>, mais le test au <strong>vasoconstricteur</strong> et l'intensité douloureuse <span class=\"kw-clinique\">les</span> opposent — la sclérite étant la plus grave par son association systémique et son risque de complications oculaires.</p>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Épisclérite</th><th>Sclérite</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Inflammation de l'<span class=\"kw-def\">épisclère</span> (sous la conjonctive)</td>\n            <td>Inflammation de la <span class=\"kw-def\">sclère</span></td>\n          </tr>\n          <tr>\n            <td><strong>Latéralité</strong></td>\n            <td>Unilatérale</td>\n            <td>Unilatérale</td>\n          </tr>\n          <tr>\n            <td><strong>Douleur</strong></td>\n            <td>Modérée</td>\n            <td>\n              <span class=\"kw-clinique\">Douleurs ciliaires importantes</span> :<br>\n              <strong>Facteur aggravant :</strong> mobilisation du globe<br>\n              <strong>Horaire :</strong> insomniantes, réveillent en fin de nuit<br>\n              <strong><span class=\"kw-clinique\">Irradiation</span> :</strong> au-dessus et autour de l'orbite, parfois oreille ou mâchoire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Rougeur</strong></td>\n            <td>\n              En secteur (parfois diffuse)<br>\n              <span class=\"kw-clinique\">Disparaît à l'instillation d'un vasoconstricteur</span> (chlorhydrate de phényléphrine, néosynéphrine) ✅\n            </td>\n            <td>\n              Plane ou nodulaire, en secteur ou diffuse<br>\n              <span class=\"kw-clinique\">Ne disparaît pas au vasoconstricteur</span> ❌\n            </td>\n          </tr>\n          <tr>\n            <td><strong>BAV</strong></td>\n            <td>Non</td>\n            <td>Non, sauf <span class=\"kw-alerte\">complications</span> : scléro-uvéite, sclérite postérieure, effusion uvéale</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan étiologique</strong></td>\n            <td>\n              Pas de bilan au 1ᵉʳ épisode<br>\n              Bilan identique à la sclérite si <strong>récidivante</strong>\n            </td>\n            <td><span class=\"kw-ttt\">Bilan étiologique dès le 1ᵉʳ épisode obligatoire</span> ✅ (consultation médecine interne)</td>\n          </tr>\n          <tr>\n            <td><strong>Étiologie</strong></td>\n            <td>Idiopathique le plus souvent ; étiologies de sclérite à rechercher si récidive</td>\n            <td>\n              <strong>Articulaire :</strong> SpA, <span class=\"kw-clinique\">PR</span>, <span class=\"kw-def\">lupus</span> érythémateux disséminé<br>\n              <strong>Vasculaire :</strong> PAN, <span class=\"kw-clinique\">GPA</span> (Wegener), cryoglobulinémie, Behçet (plus rare)<br>\n              <strong>Digestif :</strong> <span class=\"kw-def\">MICI</span><br>\n              <strong>Cutané :</strong> <span class=\"kw-clinique\">psoriasis</span>, <span class=\"kw-def\">lupus</span><br>\n              <strong>Bronchopulmonaire :</strong> polychondrite atrophiante, <span class=\"kw-clinique\">sarcoïdose</span> (plus rare)<br>\n              <strong><span class=\"kw-etio\">Infectieux</span> :</strong> <span class=\"kw-def\">tuberculose</span>, herpès/<span class=\"kw-clinique\">zona</span>, borréliose, infection locale à pyocyanique\n            </td>\n          </tr>\n          <tr>\n            <td><em>Traitement (supprimé de la dernière édition)</em></td>\n            <td><em><span class=\"kw-ttt\">AINS</span> locaux ou CTC locaux</em></td>\n            <td>\n              <em><span class=\"kw-ttt\">AINS</span> PO en 1ʳᵉ intention<br>\n              CTC en collyre si forme non grave<br>\n              CTC systémique (ou <span class=\"kw-ttt\">immunosuppresseurs</span>, biothérapies) si forme grave : <span class=\"kw-clinique\">nécrose</span> sclérale (scléromalacie), kératite périphérique ulcérante, BAV par complication<br>\n              Relais adapté à l'étiologie</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> Le <span class=\"kw-clinique\">test au vasoconstricteur</span> au cabinet (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>outte de néosynéphrine) — <span class=\"kw-clinique\">disparition de la rougeur</span> = épisclérite (rassurant) ; <span class=\"kw-clinique\">persistance</span> = sclérite (à explorer en interne).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 197 — Spondylarthrite <span class=\"kw-etio\">inflammatoire</span> · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 195 — Artérite à cellules géantes</em></p>","frequence":0},{"id":"83-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir devant un œil rouge douloureux avec baisse de l’acuité visuelle (BAV)","contenu":"<p>Œil rouge + douleur + <strong>BAV</strong> = <span class=\"kw-alerte\">urgence ophtalmologique</span>. Quatre diagnostics dominent et imposent l'avis ophtalmologique immédiat à la <span class=\"kw-clinique\">lampe à fente</span> : <strong>kératite</strong>, <strong>uvéite antérieure</strong>, <strong>endophtalmie</strong> et <strong>glaucome aigu par fermeture de l'angle</strong> (le dernier débordant l'item 83 mais à connaître comme DD).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> vitale fonctionnelle.</strong> Le <span class=\"kw-def\">pronostic</span> visuel se joue dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">premières heures</span>. Aucun traitement local empirique (en particulier <span class=\"kw-alerte\">JAMAIS de CTC à l'aveugle</span>) avant l'examen ophtalmologique — risque de perforation cornéenne sur kératite herpétique non diagnostiquée.\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Diagnostic</th><th>Pivot diagnostique</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Kératite (incluant <span class=\"kw-clinique\">abcès</span> de cornée)</strong></td>\n            <td>\n              Douleur superficielle intense + photophobie + blépharospasme<br>\n              <span class=\"kw-clinique\">Test à la fluorescéine positif</span> : ulcère dendritique (<span class=\"kw-etio\">HSV</span>), ponctuée (sécheresse/<span class=\"kw-etio\">adénovirus</span>), plage (<span class=\"kw-clinique\">abcès</span>)<br>\n              <span class=\"kw-clinique\">Opacification cornéenne</span> blanchâtre si <span class=\"kw-clinique\">abcès</span><br>\n              <span class=\"kw-def\">Terrain</span> : port de <span class=\"kw-clinique\">lentilles</span>, ATCD herpès, traumatisme épithélial\n            </td>\n            <td>\n              <strong>Prélèvement à l'écouvillon</strong> au niveau de l'<span class=\"kw-clinique\">abcès</span> (direct, culture, biomol, ATBgramme)<br>\n              <strong>ATB topiques</strong> empiriques (<span class=\"kw-ttt\">ciprofloxacine</span>, <span class=\"kw-ttt\">tobramycine</span>) si forme précoce<br>\n              <strong>Collyres ATB fortifiés horaire</strong> en <span class=\"kw-alerte\">hospitalisation</span> si <span class=\"kw-clinique\">abcès</span> important (<span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">ceftazidime</span> ou amikacine)<br>\n              <strong>ATB systémique</strong> associé si risque de <span class=\"kw-imagerie\">diffusion</span><br>\n              <strong>Antiviraux</strong> (<span class=\"kw-ttt\">valaciclovir</span> PO, <span class=\"kw-ttt\">aciclovir</span> IV si sévère) si <span class=\"kw-etio\">HSV</span>/VZV\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Uvéite antérieure</strong></td>\n            <td>\n              Douleur profonde modérée, <span class=\"kw-clinique\">irradiation</span> sus-orbitaire<br>\n              <span class=\"kw-clinique\">Myosis relatif</span><br>\n              <span class=\"kw-clinique\">Tyndall</span> en chambre antérieure (« phare dans le brouillard »)<br>\n              <span class=\"kw-clinique\">Précipités rétrocornéens</span> ± hypopion<br>\n              <span class=\"kw-clinique\">Synéchies postérieures</span> (déformation pupillaire à la dilatation)\n            </td>\n            <td>\n              <strong>Collyres mydriatiques</strong> (<span class=\"kw-ttt\">atropine</span>) pour rompre/prévenir <span class=\"kw-clinique\">les</span> synéchies<br>\n              <strong>Collyres <span class=\"kw-ttt\">corticoïdes</span></strong> + pommade nocturne<br>\n              <strong>Bilan étiologique systématique</strong> (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">VS</span>, Ag <span class=\"kw-bio\">HLA-B27</span>, <span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-clinique\">IDR</span>, ECA, TPHA-VDRL, <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">HSV</span>/VZV)<br>\n              Traitement étiologique (SpA, <span class=\"kw-clinique\">sarcoïdose</span>, herpès)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endophtalmie postopératoire</strong></td>\n            <td>\n              Contexte : <span class=\"kw-clinique\">2–7 jours après chirurgie cataracte</span>, après IVT (anti-VEGF, CTC), ou à distance d'une <span class=\"kw-ttt\">chirurgie</span> du glaucome<br>\n              BAV totale quasi-constante + douleur intense + <span class=\"kw-clinique\">irradiation</span> sus-orbitaire<br>\n              <span class=\"kw-clinique\">Œdème</span> palpébral, <span class=\"kw-bio\">fibrine</span> en CA, <span class=\"kw-clinique\">hypopion</span>, cercle périkératique<br>\n              <span class=\"kw-clinique\">Hyalite</span> limitant la visualisation du <span class=\"kw-imagerie\">FO</span>\n            </td>\n            <td>\n              <strong><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span></strong> 🏥<br>\n              <strong>Prélèvement bactériologique :</strong> <span class=\"kw-ttt\">ponction</span> du vitré (ou de chambre antérieure à défaut)<br>\n              <strong>IVT d’ATB</strong> (<span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">ceftazidime</span>)<br>\n              <strong>ATB systémique</strong> à bonne pénétration intra-oculaire (<span class=\"kw-ttt\">lévofloxacine</span> + <span class=\"kw-ttt\">imipénème</span>)<br>\n              <strong>Vitrectomie postérieure</strong> d'emblée si sévère, ou en sauvetage<br>\n              CTC selon <span class=\"kw-clinique\">les</span> équipes\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Glaucome aigu par fermeture de l’angle</strong> <em>(DD hors item 83)</em></td>\n            <td>\n              Douleur péri-orbitaire violente, BAV brutale, halos colorés, <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">cornée œdémateuse</span> trouble, mydriase aréflexique, chambre antérieure <span class=\"kw-clinique\">étroite</span>, tonus oculaire ≫<span class=\"kw-chiffre\"> 30 mmHg</span>\n            </td>\n            <td><span class=\"kw-alerte\">Urgence</span> — voir item 84 (glaucomes) : hypotonisants IV (acétazolamide), collyres myotiques + osmotiques, iridotomie au <span class=\"kw-ttt\">laser</span> secondairement</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Élément décisionnel</th><th>Action</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Lampe à fente (LAF)</strong></td>\n            <td>Examen <span class=\"kw-clinique\">systématique</span> et immédiat — différencie kératite / uvéite / endophtalmie / glaucome aigu</td>\n          </tr>\n          <tr>\n            <td><strong>Test à la fluorescéine</strong></td>\n            <td>Systématique en cas de douleur cornéenne — oriente vers la nature de l'<span class=\"kw-clinique\">ulcération</span></td>\n          </tr>\n          <tr>\n            <td><strong>Tonus oculaire</strong></td>\n            <td>Élimine un glaucome aigu (HTO ≫<span class=\"kw-chiffre\"> 30 mmHg</span>) ; recherche une hypertonie d'uvéite herpétique ou de Posner-Schlossman</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">FO</span> + B-scan</strong></td>\n            <td>Si milieux opaques (endophtalmie, hyalite dense) — pour évaluer le segment postérieur</td>\n          </tr>\n          <tr>\n            <td><strong>Avis ophtalmologique en <span class=\"kw-alerte\">urgence</span></strong></td>\n            <td>Systématique — orientation hospitalière si endophtalmie, <span class=\"kw-clinique\">abcès</span> grave, uvéite avec hypopion, BAV brutale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège QCM ⭐⭐⭐⭐.</strong> Toute prescription de <span class=\"kw-alerte\">corticoïdes locaux à l'aveugle</span> sur un œil rouge douloureux est <span class=\"kw-alerte\">contre-indiquée</span> — risque de <strong>perforation cornéenne</strong> sur kératite herpétique méconnue. Examen LAF + écarter une kératite herpétique = pré-requis absolu avant tout collyre CTC.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision · 84 — Glaucome chronique · 168 — Herpesvirus · 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":4},{"id":"83-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une kératite","contenu":"<p>Kératite = <span class=\"kw-def\">atteinte cornéenne</span> (épithéliale, ulcérative ou stromale infiltrative), aiguë ou chronique, donnant le tableau pivot <strong>œil rouge douloureux AVEC BAV</strong>. Le <span class=\"kw-def\">diagnostic positif</span> repose sur la <span class=\"kw-clinique\">lampe à fente</span> + <span class=\"kw-clinique\">test à la fluorescéine</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Manifestations</strong></td>\n            <td>\n              <strong>BAV :</strong> variable selon la <span class=\"kw-clinique\">position de l'atteinte par rapport à l'axe visuel</span><br>\n              <strong>Douleur :</strong> superficielle intense — corps étranger, piqûre, déchirure, arrachement<br>\n              <strong>Larmoiement réflexe</strong> · <strong>photophobie</strong> · <strong>blépharospasme</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen à la LAF</strong></td>\n            <td>\n              Instillation d'<span class=\"kw-ttt\">anesthésique topique</span> (oxybuprocaïne, tétracaïne) — <span class=\"kw-alerte\">jamais en prescription répétée ou prolongée</span> (risque de perforation cornéenne)<br>\n              <strong>Test à la fluorescéine :</strong> orange en lumière naturelle, <span class=\"kw-clinique\">vert en lumière bleue</span> (filtre jaune renforce)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Lésions visibles</strong></td>\n            <td>\n              <strong>Érosions / ulcérations</strong> de la cornée (visibles fluo+)<br>\n              <strong>Opacification cornéenne</strong> en regard de l'<span class=\"kw-clinique\">ulcération</span><br>\n              <strong>Cercle périkératique</strong><br>\n              <strong>Chambre antérieure :</strong> profondeur normale, parfois réaction <span class=\"kw-etio\">inflammatoire</span> si sévère\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Aspects à la fluorescéine</h4>\n      <table >\n        <thead>\n          <tr><th>Aspect à la fluorescéine</th><th>Orientation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Ulcération</span> unique régulière</strong></td><td><span class=\"kw-clinique\">traumatisme</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Ulcération</span> localisée + zone blanche adjacente</strong></td><td><span class=\"kw-alerte\">abcès de cornée</span> (<span class=\"kw-etio\">bactérien</span>, fongique) ou <span class=\"kw-ttt\">infiltration</span> <span class=\"kw-etio\">inflammatoire</span> stérile</td></tr>\n          <tr><td><strong>Ulcère dendritique en feuille de fougère</strong></td><td><span class=\"kw-alerte\">kératite herpétique</span> ⭐ — <span class=\"kw-ci\">CI absolue</span> aux CTC locaux et aux anesthésiques locaux</td></tr>\n          <tr><td><strong>Kératite ponctuée superficielle (KPS)</strong></td><td>syndrome sec, kérato-conjonctivite à <span class=\"kw-etio\">adénovirus</span>, kératite zostérienne</td></tr>\n          <tr><td><strong>Lésions linéaires</strong></td><td><span class=\"kw-clinique\">CE sous la paupière supérieure</span> passé inaperçu (à éverser systématiquement)</td></tr>\n          <tr><td><strong>Signe de Seidel</strong> (lavage de la fluorescéine par l'humeur aqueuse)</td><td><span class=\"kw-alerte\">plaie cornéenne pénétrante</span> avec sortie d'humeur aqueuse — rechercher un CE intra-oculaire</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Comparaison des trois grands tableaux</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>KPS</th><th>Ulcère de cornée</th><th><span class=\"kw-clinique\">Abcès</span> de cornée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptôme</strong></td>\n            <td>Douleur modérée + BAV modérée</td>\n            <td>Douleur + BAV si axe visuel</td>\n            <td>Douleur majeure + BAV si axe visuel</td>\n          </tr>\n          <tr>\n            <td><strong>Œil</strong></td>\n            <td>Rouge</td>\n            <td>Rouge, sans opacification cornéenne</td>\n            <td>Rouge, opacification blanchâtre mal limitée (<span class=\"kw-ttt\">infiltration</span> stromale)</td>\n          </tr>\n          <tr>\n            <td><strong>Fluorescéine</strong></td>\n            <td>Punctiforme superficielle</td>\n            <td>Plage bien limitée</td>\n            <td>Prise de fluo au foyer d'<span class=\"kw-ttt\">infiltration</span></td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies</strong></td>\n            <td>Sécheresse, <span class=\"kw-etio\">adénovirus</span>, kératite d'exposition, conjonctivite <span class=\"kw-etio\">allergique</span>, kératite herpétique</td>\n            <td>Traumatisme (unique régulier), <span class=\"kw-etio\">HSV</span> (dendritique), CE (linéaire), sécheresse, exposition</td>\n            <td>Surinfection <span class=\"kw-etio\">bactérienne</span> (pyocyanique +++, CG+), fongique (Fusarium, <span class=\"kw-etio\">Candida</span>, Aspergillus), amibienne (porteurs de lentilles)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Formes infectieuses spécifiques</h4>\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Kératite à pyogènes (<span class=\"kw-clinique\">abcès</span>)</strong></td>\n            <td>\n              <strong>Germes :</strong> bacille pyocyanique +++ (lésions destructrices), CG+ (staph, strep)<br>\n              <strong>Facteurs favorisants :</strong> port inadapté de lentilles ++, traumatisme épithélial, anomalies palpébrales (entropion, ectropion, lagophtalmie), CTC prolongés, immunosuppression<br>\n              <strong>Présentation :</strong> douleur majeure + BAV + opacification blanchâtre + hypopion possible\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Kératite <span class=\"kw-etio\">fongique</span></strong></td>\n            <td><span class=\"kw-bio\">Fusarium, Candida, Aspergillus</span> — plus rares, volontiers sévères, infiltrent en surface et en profondeur ; TTT <span class=\"kw-ttt\">antifongique</span> intense et prolongé (<span class=\"kw-ttt\">amphotéricine, voriconazole</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Kératite amibienne</strong></td>\n            <td>Apanage du <span class=\"kw-clinique\">porteur de lentilles</span> ; installation insidieuse — infiltrations linéaires régressives sous antiseptique, parfois <span class=\"kw-clinique\">évolution</span> vers une <span class=\"kw-alerte\">scléro-kératite annulaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Kératite à <span class=\"kw-etio\">adénovirus</span></strong></td>\n            <td>Complique une conjonctivite à <span class=\"kw-etio\">adénovirus</span> (épidémique) ; KPS à la fluo, opacités stromales antérieures à risque de séquelles si centrales ; TTT symptomatique + CTC topiques lentement dégressifs si opacités</td>\n          </tr>\n          <tr>\n            <td><strong>Kératite herpétique (<span class=\"kw-etio\">HSV</span>)</strong></td>\n            <td>\n              <strong>Cause :</strong> <span class=\"kw-clinique\">primo-infection</span> ou récurrence HSV1 &gt; HSV2 ; unilatérale<br>\n              <strong>Clinique :</strong> œil rouge sans opacité initiale, douleur superficielle intense, BAV, larmoiement, photophobie, blépharospasme ; <span class=\"kw-clinique\">vésicules palpébrales</span> ⭐ et <span class=\"kw-clinique\">adénopathie</span> prétragienne<br>\n              <strong>Fluo :</strong> <span class=\"kw-clinique\">ulcère dendritique</span> (feuille de fougère) typique ou « en carte de géographie »<br>\n              <strong>Bilan :</strong> rechercher signes d'uvéite antérieure associée + atteinte <span class=\"kw-imagerie\">FO</span> ; prélèvement <span class=\"kw-bio\">PCR</span> si forme atypique ou résistance<br>\n              <strong>TTT :</strong> <span class=\"kw-ttt\">valaciclovir/aciclovir PO</span> ou <span class=\"kw-ttt\">aciclovir</span> topique (pommade), ou <span class=\"kw-ttt\">aciclovir</span> IV + topique si kératite profonde / uvéite / <span class=\"kw-clinique\">nécrose</span> rétinienne ; prophylaxie orale si &gt; 6 récurrences/an<br>\n              <strong>⚠️ <span class=\"kw-ci\">CI absolue</span> :</strong> CTC locaux (perforation) et anesthésiques locaux\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Kératite zostérienne (<span class=\"kw-etio\">VZV</span>)</strong></td>\n            <td>\n              Complique un <span class=\"kw-clinique\">zona ophtalmique</span> (V1) chez le &gt;<span class=\"kw-chiffre\"> 50 ans</span> ; <span class=\"kw-clinique\">éruption</span> frontale, lacrymale, nasale externe (signe d'Hutchinson) ou interne<br>\n              <strong>Plaques virales :</strong> dendritiformes en fougère à la fluo<br>\n              <strong>TTT :</strong> <span class=\"kw-ttt\">valaciclovir/famciclovir PO 7 j</span> si immunocompétent (dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">72 h</span>) ; <span class=\"kw-ttt\">aciclovir IV 7–10 j</span> si immunodéprimé ; pommade <span class=\"kw-ttt\">aciclovir</span> + substituts lacrymaux<br>\n              <strong>Risques :</strong> surinfection (<span class=\"kw-clinique\">cellulite</span> orbitaire, <span class=\"kw-clinique\">abcès</span>), kératite stromale, <span class=\"kw-clinique\">kératite neuroparalytique/neurotrophique</span> (anesthésie cornéenne séquellaire de V1, ulcérations à 2–3 sem post-<span class=\"kw-clinique\">éruption</span>), uvéite, paralysies oculomotrices, séquelles définitives\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Kératites non infectieuses</h4>\n      <ul>\n        <li><strong>Infiltrats inflammatoires non <span class=\"kw-etio\">infectieux</span> :</strong> périphériques, blanchâtres ± ulcérés ; principal DD des <span class=\"kw-clinique\">abcès</span> ; cause principale = <span class=\"kw-clinique\">rosacée oculaire</span></li>\n        <li><strong>Kératite sur syndrome sec :</strong> KPS, ulcère susceptible de se surinfecter</li>\n        <li><strong>Kératite d'exposition :</strong> <span class=\"kw-clinique\">paralysie faciale</span> → mauvaise occlusion palpébrale → altération épithéliale ; TTT par protecteurs cornéens, voire <span class=\"kw-clinique\">tarsorraphie</span> pour réduire la fente palpébrale</li>\n      </ul>\n\n      <h4>Complications des kératites infectieuses</h4>\n      <ul>\n        <li><strong>Endophtalmie</strong> en aigu (extension postérieure)</li>\n        <li><strong>Perforation cornéenne</strong> en aigu — indication de <span class=\"kw-ttt\">greffe de cornée « à chaud »</span></li>\n        <li><strong>Taie cornéenne cicatricielle</strong> à distance — BAV si axe visuel, indication de <span class=\"kw-ttt\">greffe « à froid »</span></li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> <span class=\"kw-alerte\">Ulcère dendritique = HSV</span> jusqu'à preuve du contraire → <span class=\"kw-alerte\">corticothérapie locale formellement contre-indiquée</span> (perforation cornéenne). Toute kératite chez un porteur de lentilles → suspecter un <span class=\"kw-alerte\">pyocyanique</span> ou une <span class=\"kw-alerte\">amibe</span> (Acanthamoeba).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus · 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":1},{"id":"83-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","contenu":"<div class=\"callout callout-warn\">\n        <strong>Objectif « hot » EDN.</strong> Compté <strong>11 fois</strong> dans <span class=\"kw-clinique\">les</span> QCM EDN (option C cappée à 5⭐). C'est le pivot ophtalmologique de la médecine interne — toujours rechercher l'étiologie systémique sous-jacente (SpA <span class=\"kw-bio\">HLA-B27</span>+, <span class=\"kw-clinique\">sarcoïdose</span>, herpès, Behçet, AJI chez l'enfant).\n      </div>\n\n      <p>Uvéite = <span class=\"kw-def\">inflammation de l'uvée</span> (iris, corps ciliaire, choroïde) classée selon la topographie : <strong>antérieure</strong> (iridocyclite — la plus fréquente), <strong>intermédiaire</strong> (vitré principal), <strong>postérieure</strong> (choroïde/rétine), <strong>panuvéite</strong> (tout l'œil).</p>\n\n      <h4>1. Uvéite antérieure (iridocyclite) — la plus fréquente</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Localisation</strong></td>\n            <td>Iris (iritis) + corps ciliaire (cyclite)</td>\n          </tr>\n          <tr>\n            <td><strong>Latéralité</strong></td>\n            <td>Uni- ou bilatérale, parfois récidivante et <span class=\"kw-clinique\">à bascule</span></td>\n          </tr>\n          <tr>\n            <td><strong>Présentation</strong></td>\n            <td>Œil rouge + BAV variable + <span class=\"kw-clinique\">douleurs profondes modérées sus-orbitaires</span></td>\n          </tr>\n          <tr>\n            <td><strong>Pupille</strong></td>\n            <td><span class=\"kw-clinique\">Myosis relatif</span> ⭐</td>\n          </tr>\n          <tr>\n            <td><strong>Segment antérieur</strong></td>\n            <td>\n              <strong>Transparence cornéenne normale</strong> ⭐<br>\n              <strong>Injection ciliaire périkératique</strong> (témoin de l'inflammation intra-oculaire)<br>\n              <strong>Synéchies postérieures</strong> (adhérences irido-cristalliniennes) — déformation pupillaire dévoilée à la dilatation<br>\n              <strong>Synéchies antérieures</strong> (irido-cornéennes) — visibles en gonioscopie<br>\n              <strong>Tyndall</strong> (protéines / cellules inflammatoires en humeur aqueuse) — « phare dans le brouillard » à la projection lumineuse LAF<br>\n              <strong>Précipités rétrocornéens</strong> (rétrodescemétiques) :<br>\n              &nbsp;&nbsp;→ <strong>Non granulomateux</strong> (fins) : <em>SpA, <span class=\"kw-clinique\">Behçet</span>, <span class=\"kw-clinique\">syphilis</span></em><br>\n              &nbsp;&nbsp;→ <strong>Granulomateux</strong> (« en graisse de mouton ») : <em><span class=\"kw-clinique\">sarcoïdose</span>, <span class=\"kw-def\">tuberculose</span>, SEP, syphilis, herpès</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Segment postérieur</strong></td>\n            <td><span class=\"kw-clinique\">FO systématique</span> — recherche d'atteinte <span class=\"kw-etio\">inflammatoire</span> vitréenne (hyalite), rétinienne ou choroïdienne (= uvéite postérieure ou panuvéite)</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td>\n              <strong>Étiologique :</strong> infection ou maladie générale identifiée<br>\n              <strong>Local systématique :</strong><br>\n              &nbsp;&nbsp;→ <span class=\"kw-ttt\">Collyres mydriatiques (atropine)</span> pour rompre / prévenir <span class=\"kw-clinique\">les</span> synéchies postérieures<br>\n              &nbsp;&nbsp;→ <span class=\"kw-ttt\">Collyres corticoïdes</span> + pommade pour la nuit\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Complications</strong></td>\n            <td>\n              <strong>Cataracte secondaire</strong> (inflammation prolongée + CTC) — PEC comme cataracte liée à l'âge sous <span class=\"kw-ttt\">AINS</span><br>\n              <strong>Glaucome chronique</strong> (hypertonie + CTC) — TTT classique du glaucome + contrôle inflammation\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Enquête étiologique d'une uvéite antérieure</h4>\n      <p>Indispensable, même si elle reste fréquemment <span class=\"kw-clinique\">négative (1/3 à 1/2 des cas)</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Caractéristiques cliniques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>SpA <span class=\"kw-bio\">HLA-B27</span>+</strong></td>\n            <td>\n              <span class=\"kw-clinique\">1ʳᵉ cause</span> d'uvéite antérieure aiguë — survient dans <span class=\"kw-chiffre\">20 %</span> des SpA, peut être inaugurale<br>\n              <strong>Latéralité :</strong> unilatérale, bilatérale, ou à <span class=\"kw-clinique\">bascule</span>, récidivante<br>\n              <strong>Intensité :</strong> souvent paucisymptomatique, parfois sévère<br>\n              <strong>Segment antérieur :</strong> aspect plastique, synéchiant, souvent à <span class=\"kw-clinique\">hypopion</span><br>\n              <strong>Précipités :</strong> non granulomateux (CI granulomateux : « en graisse de mouton », nodules de Koeppe au bord pupillaire, nodules de Busacca stroma irien)<br>\n              <strong>Segment postérieur :</strong> rarement atteint<br>\n              <strong>TTT :</strong> collyres CTC + mydriatiques — bon <span class=\"kw-def\">pronostic</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Uvéite herpétique</strong></td>\n            <td>Cause infectieuse la plus fréquente — <span class=\"kw-def\">terrain</span> ATCD herpès oculaire ; uvéite antérieure granulomateuse avec <span class=\"kw-clinique\">hypertonie</span> ou <span class=\"kw-clinique\">atrophie sectorielle de l'iris</span></td>\n          </tr>\n          <tr>\n            <td><strong>Arthrite juvénile idiopathique (AJI)</strong></td>\n            <td>\n              Principale cause d'uvéite antérieure <span class=\"kw-clinique\">chez l'enfant</span> 👦🏻<br>\n              Sévérité par <span class=\"kw-alerte\">chronicité</span> + complications : <span class=\"kw-clinique\">cataracte</span>, <span class=\"kw-clinique\">kératite en bandelette</span> (dépôts calcifiés blanchâtres/grisâtres), glaucome\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Sarcoïdose</span></strong></td>\n            <td>\n              Maladie générale la plus régulièrement retrouvée — dépôts rétrodescemétiques <span class=\"kw-clinique\">granulomateux</span>, nodules iriens fréquents ; atteinte postérieure souvent associée → <span class=\"kw-clinique\">panuvéite</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maladie de <span class=\"kw-clinique\">Behçet</span></strong></td>\n            <td>Uvéite antérieure récidivante à <span class=\"kw-clinique\">hypopion</span> (rarement isolée, plutôt panuvéite) ; atteinte postérieure : hyalite, <span class=\"kw-def\">vascularite</span> rétinienne occlusive, foyers de rétinite <span class=\"kw-etio\">inflammatoire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cyclite chronique de Fuchs</strong></td>\n            <td>Uvéite à <span class=\"kw-clinique\">œil blanc</span>, non synéchiante ; précipités rétrocornéens spiculés ; hétérochromie irienne parfois ; complications : cataracte, glaucome</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Syndrome de Posner</span>-Schlossman</strong></td>\n            <td>Crises glaucomato-cyclitiques (uvéite + <span class=\"kw-clinique\">hypertension</span> intra-oculaire) récurrentes, violentes ; origine <span class=\"kw-etio\">virale</span> fréquente</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td><span class=\"kw-clinique\">Syphilis</span> (« la grande simulatrice »)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus : uvéite antérieure à hypopion → 3 causes principales</h4>\n      <ul>\n        <li><strong>SpA <span class=\"kw-bio\">HLA-B27</span>+</strong></li>\n        <li><strong>Maladie de <span class=\"kw-clinique\">Behçet</span></strong></li>\n        <li><strong>Endophtalmie postopératoire</strong></li>\n      </ul>\n\n      <h4>Bilan étiologique minimal d'une uvéite antérieure</h4>\n      <table >\n        <thead>\n          <tr><th>Recherche</th><th>Examens</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Inflammation</strong></td>\n            <td><span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">VS</span>, <span class=\"kw-bio\">EPP</span></td>\n          </tr>\n          <tr>\n            <td><strong>SpA</strong></td>\n            <td><span class=\"kw-bio\">Ag HLA-B27</span>, Rx rachis/bassin</td>\n          </tr>\n          <tr>\n            <td><strong>BK / <span class=\"kw-clinique\">sarcoïdose</span></strong></td>\n            <td><span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-clinique\">IDR</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Sarcoïdose</span></strong></td>\n            <td><span class=\"kw-bio\">Enzyme de conversion de l'angiotensine (ECA)</span>, bilan phosphocalcique, <span class=\"kw-bio\">ionogramme</span>/<span class=\"kw-bio\">urée</span>/<span class=\"kw-bio\">créatinine</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Syphilis</span></strong></td>\n            <td><span class=\"kw-bio\">TPHA-VDRL</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. Uvéite intermédiaire</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Sous-groupe d'uvéites où le <span class=\"kw-def\">vitré est le site principal</span> de l'inflammation</td>\n          </tr>\n          <tr>\n            <td><strong>Présentation</strong></td>\n            <td>BAV non brutale (rapidement progressive sur jours) + <span class=\"kw-clinique\">œil blanc</span> + indolore + <span class=\"kw-clinique\">myodésopsies</span></td>\n          </tr>\n          <tr>\n            <td><strong>Examen</strong></td>\n            <td>LAF : trouble du vitré avec cellules inflammatoires (hyalite) ; <span class=\"kw-imagerie\">FO</span> : mal visible par trouble des milieux</td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies associées</strong></td>\n            <td><span class=\"kw-def\">Vascularite</span> rétinienne périphérique, <span class=\"kw-clinique\">œdème</span> maculaire ; <strong>pars planite</strong> = forme isolée/idiopathique sans cause systémique ; <em><span class=\"kw-clinique\">sarcoïdose</span>, SEP, <span class=\"kw-def\">MICI</span>, Lyme, <span class=\"kw-clinique\">syphilis</span></em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3. Uvéites postérieures</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>Choroïde (choroïdite), rétine (rétinite) ou <span class=\"kw-clinique\">les</span> deux (choriorétinite / rétinochoroïdite)</td>\n          </tr>\n          <tr>\n            <td><strong>Œil</strong></td>\n            <td>Soit <span class=\"kw-clinique\">d'aspect extérieur normal</span> ; soit œil rouge avec douleurs ciliaires (<span class=\"kw-etio\">HSV</span>, VZV)</td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <strong>Myodésopsies</strong> (points noirs, mouches volantes, corps flottants)<br>\n              <strong>BAV si :</strong> uvéite antérieure associée ; hyalite (BAV progressive par trouble des milieux) ; <span class=\"kw-alerte\">atteinte maculaire ou du nerf optique</span> (BAV brutale)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">FO</span></strong></td>\n            <td>Après dilatation, <span class=\"kw-clinique\">confirme le diagnostic</span> — souvent associé à une hyalite (vitré trouble gênant le <span class=\"kw-imagerie\">FO</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Risques</strong></td>\n            <td>\n              Atteinte <span class=\"kw-alerte\">maculaire</span>, vasculaire ou papillaire <span class=\"kw-alerte\">irrémédiable</span><br>\n              Complications rétiniennes : <span class=\"kw-clinique\">œdème</span> maculaire cystoïde, DR tractionnel\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Étiologies</strong></td>\n            <td>\n              <strong>Infectieuses :</strong> toxoplasmose, <span class=\"kw-etio\">HSV</span>, VZV, CMV (immunodéprimé), <span class=\"kw-clinique\">syphilis</span>, bartonellose, <span class=\"kw-def\">tuberculose</span><br>\n              <strong>Systémiques :</strong> <span class=\"kw-clinique\">sarcoïdose</span> (fréquente ++), maladie de Behçet (risque fonctionnel ++)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus toxoplasmose oculaire (chorio-rétinite)</h4>\n      <ul>\n        <li><strong>Rétinochoroïdite toxoplasmique</strong> = uvéite infectieuse <span class=\"kw-clinique\">la plus fréquente</span>, d'origine <span class=\"kw-clinique\">acquise</span> plus que <span class=\"kw-etio\">congénitale</span></li>\n        <li><strong><span class=\"kw-imagerie\">FO</span> :</strong> foyer blanchâtre évoluant vers une cicatrice atrophique d'où peuvent survenir des récidives</li>\n        <li><strong>Caractéristique :</strong> <span class=\"kw-clinique\">évolution</span> en foyer, risque de récidive <span class=\"kw-clinique\">toute la vie</span></li>\n        <li><strong>TTT</strong> (si <span class=\"kw-alerte\">menace</span> pour l'acuité visuelle) : <span class=\"kw-ttt\">pyriméthamine + sulfadiazine</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Prise en charge globale de l'uvéite postérieure / panuvéite.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Hospitalisation</span> en <strong><span class=\"kw-alerte\">urgence</span></strong> 🏥</li>\n          <li><span class=\"kw-bio\">Sérologie</span> <strong><span class=\"kw-etio\">VIH</span></strong></li>\n          <li><span class=\"kw-ttt\">Ponction</span> de chambre antérieure : virologie (<span class=\"kw-bio\">PCR</span> <span class=\"kw-etio\">HSV</span>, VZV, CMV), parasitologie (toxoplasmose), bactériologie standard</li>\n          <li>Traitement <strong>par voie générale en <span class=\"kw-alerte\">urgence</span></strong> selon l'étiologie : <span class=\"kw-ttt\">antiviral</span>, antitoxoplasme avec CTC systémique</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège du sujet âgé.</strong> Devant un tableau de <span class=\"kw-clinique\">hyalite dense</span> chez le sujet âgé, rechercher un <span class=\"kw-alerte\">lymphome oculo-cérébral primitif</span> et réaliser un prélèvement vitréen pour analyse cytologique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 197 — Spondylarthrite <span class=\"kw-etio\">inflammatoire</span> · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 168 — Herpesvirus · 169 — <span class=\"kw-etio\">VIH</span> · 162 — <span class=\"kw-clinique\">IST</span> · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":11},{"id":"83-9","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir réaliser un prélèvement conjonctival","contenu":"<p>Le prélèvement conjonctival n'est <strong>pas systématique</strong> dans la conjonctivite <span class=\"kw-etio\">bactérienne</span> aiguë de l'adulte sain — il est réservé aux situations où le traitement empirique a échoué ou aux formes graves/inhabituelles.</p>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>\n              <strong>Conjonctivite <span class=\"kw-etio\">bactérienne</span> :</strong> forme <span class=\"kw-clinique\">grave</span> ou <span class=\"kw-clinique\">résistante au traitement de 1ʳᵉ ligne</span><br>\n              <strong>Conjonctivite <span class=\"kw-etio\">virale</span> :</strong> test diagnostique rapide sur échantillon lacrymal si doute avec une bactérienne<br>\n              <strong>Conjonctivite chronique :</strong> recherche de <em><span class=\"kw-clinique\">Chlamydia</span> trachomatis</em>, Bartonella henselae, mycobactéries<br>\n              <strong>Nouveau-né</strong> (ophtalmie néonatale) : recherche systématique de Chlamydia, gonocoque, <span class=\"kw-etio\">HSV</span><br>\n              <strong>Forme atypique :</strong> kérato-conjonctivite traînante, suspicion d'<span class=\"kw-clinique\">IST</span> oculaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Matériel</strong></td>\n            <td>\n              Écouvillons stériles (un par milieu de transport)<br>\n              Milieux de transport adaptés : bactériologie standard, virologie, <span class=\"kw-clinique\">Chlamydia</span> (<span class=\"kw-bio\">PCR</span>), milieux spécifiques (<span class=\"kw-etio\">fongique</span>, amibien si suspicion)<br>\n              Anesthésique topique (oxybuprocaïne ou tétracaïne) — usage ponctuel\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Technique</strong></td>\n            <td>\n              <strong>1.</strong> Anesthésie topique ponctuelle si nécessaire<br>\n              <strong>2.</strong> Demander au patient de regarder vers le haut<br>\n              <strong>3.</strong> Abaisser la paupière inférieure<br>\n              <strong>4.</strong> Frotter doucement l'écouvillon sur la <span class=\"kw-clinique\">conjonctive du cul-de-sac inférieur</span> (zone de stase des sécrétions)<br>\n              <strong>5.</strong> Acheminer rapidement vers le laboratoire dans le milieu adapté\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Analyses demandées</strong></td>\n            <td>\n              <strong>Examen direct</strong> : Gram (CG+ <span class=\"kw-bio\">vs</span> BGN), KOH (<span class=\"kw-etio\">fongique</span>), trichrome (amibe)<br>\n              <strong>Culture</strong> + <span class=\"kw-bio\">antibiogramme</span> / antifongigramme<br>\n              <strong><span class=\"kw-bio\">PCR</span></strong> : <span class=\"kw-clinique\">Chlamydia</span>, <span class=\"kw-etio\">HSV</span>, <span class=\"kw-etio\">adénovirus</span>, <span class=\"kw-clinique\">gonocoque</span> (selon orientation)<br>\n              <strong>Test rapide adénovirus</strong> : <span class=\"kw-bio\">antigène</span> détecté sur échantillon lacrymal/conjonctival\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cas particuliers</strong></td>\n            <td>\n              <strong>Kératite / <span class=\"kw-clinique\">abcès</span> de cornée :</strong> prélèvement <strong>cornéen direct</strong> au niveau de l'<span class=\"kw-clinique\">abcès</span> (différent du conjonctival) — direct + culture + biomol + <span class=\"kw-bio\">antibiogramme</span>/antifongigramme<br>\n              <strong>Endophtalmie :</strong> prélèvement par <strong><span class=\"kw-ttt\">ponction</span> du vitré</strong> (ou de chambre antérieure à défaut) — pas un prélèvement conjonctival\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pivot.</strong> Devant une conjonctivite aiguë typique de l'adulte sans facteur de gravité, traitement empirique sans prélèvement. Le prélèvement répond à une <span class=\"kw-clinique\">question clinique précise</span> : échec, forme grave, suspicion d'<span class=\"kw-clinique\">IST</span>, <span class=\"kw-def\">terrain</span> particulier (nourrisson, immunodéprimé, porteur de lentilles).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":0},{"id":"83-10","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence et les facteurs aggravants de la sécheresse oculaire","contenu":"<p>La sécheresse oculaire (kérato-conjonctivite sèche) est <span class=\"kw-clinique\">très fréquente</span>, plus souvent <span class=\"kw-clinique\">qualitative que quantitative</span>. Elle représente la <strong>1ʳᵉ étiologie de conjonctivite</strong>, par altération de la trophicité épithéliale conjonctivale ± cornéenne.</p>\n\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Hyposécrétion lacrymale (Schirmer ↓)</th><th>Altération qualitative (Schirmer normal)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Involution des glandes lacrymales</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Âge</span><br>\n              Médicaments : <span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">antidépresseurs</span><br>\n              Altération de l'arc réflexe\n            </td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Destruction des glandes lacrymales</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Gougerot-Sjögren</span> (primitif ou secondaire)<br>\n              Réaction du greffon contre l'hôte (plus rare)<br>\n              Atteinte radique (plus rare)\n            </td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Hyper-évaporation (dysfonctionnement meibomien)</strong></td>\n            <td>—</td>\n            <td>\n              <span class=\"kw-clinique\">Rosacée par blépharite chronique</span> +++ et autres atteintes inflammatoires meibomiennes chroniques<br>\n              <span class=\"kw-clinique\">Application prolongée de conservateurs</span><br>\n              <span class=\"kw-ttt\">Isotrétinoïne</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Déficit de la composante muqueuse</strong></td>\n            <td>—</td>\n            <td>\n              Atteintes conjonctivales inflammatoires/fibrosantes : <span class=\"kw-clinique\">pemphigoïde cicatricielle oculaire</span>, <span class=\"kw-alerte\">Stevens-Johnson</span>, brûlure chimique<br>\n              Infections locales étendues<br>\n              Agressions environnementales importantes\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs aggravants généraux</h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs aggravants</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Environnement</strong></td><td>vapeurs chimiques, <span class=\"kw-etio\">tabac</span>, poussière, soleil, climatisation, <span class=\"kw-def\">air</span> sec ou air chaud pulsé</td></tr>\n          <tr><td><strong>Médicaments</strong></td><td>antihistaminiques, anticholinergiques, antidépresseurs tricycliques, <span class=\"kw-ttt\">bêta-bloquants</span>, <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">isotrétinoïne</span>, chimiothérapies</td></tr>\n          <tr><td><strong>Comportementaux</strong></td><td>écrans (raréfaction du clignement), lecture prolongée, port prolongé de lentilles</td></tr>\n          <tr><td><strong>Endocrinien</strong></td><td>ménopause, déficit androgénique</td></tr>\n          <tr><td><strong>Inflammation chronique</strong></td><td>blépharite chronique, rosacée</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pivot étiologique.</strong> Devant une sécheresse oculaire sévère du sujet jeune ou d'âge moyen, rechercher systématiquement un <span class=\"kw-clinique\">Gougerot-Sjögren</span> (sec oculaire + sec buccal + auto-<span class=\"kw-bio\">anticorps anti-SSA</span>/SSB) et orienter vers la médecine interne.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span></em></p>","frequence":0},{"id":"83-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les traitements de la sécheresse oculaire","contenu":"<p>La prise en charge de la sécheresse oculaire combine <strong>substituts lacrymaux</strong>, <strong>éviction des facteurs aggravants</strong>, soins palpébraux et — dans <span class=\"kw-clinique\">les</span> cas sélectionnés — <span class=\"kw-ttt\">chirurgie</span> ou immunomodulateurs locaux.</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Mesures</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ ligne (systématique)</strong></td>\n            <td>\n              <strong>Substituts lacrymaux</strong> (idéalement <span class=\"kw-clinique\">sans conservateurs</span>) : larmes artificielles en flacons, gels en tubes<br>\n              <strong>Éviction des facteurs irritants ou aggravants :</strong>\n              <ul>\n                <li>Vapeurs chimiques, <span class=\"kw-etio\">tabac</span>, poussière</li>\n                <li>Soleil → lunettes teintées</li>\n                <li>Climatisation, <span class=\"kw-def\">air</span> sec, air chaud pulsé → humidificateurs</li>\n              </ul>\n              <strong>Amélioration de la stabilité lacrymale par soins de paupières :</strong> chauffage puis massage palpébral (facilite l'excrétion de gras par <span class=\"kw-clinique\">les</span> glandes de Meibomius — le gras diminue l'évaporation lacrymale)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Selon <span class=\"kw-clinique\">les</span> cas</strong></td>\n            <td>\n              <strong>Traitement chirurgical :</strong> occlusion <span class=\"kw-clinique\">temporaire ou permanente des points lacrymaux</span> (réduit le <span class=\"kw-ttt\">drainage</span> des larmes)<br>\n              <strong>Traitements généraux :</strong> <span class=\"kw-ttt\">parasympatholytiques sécrétagogues</span>, <span class=\"kw-ttt\">fluidifiants</span><br>\n              <strong>Traitements locaux :</strong> <span class=\"kw-ttt\">CTC locaux en cures courtes</span>, ou <span class=\"kw-ttt\">ciclosporine topique en traitement prolongé</span> dans certains cas sélectionnés<br>\n              <strong>Cas sévères :</strong> port de lunettes à chambre humide ou de <span class=\"kw-clinique\">verres scléraux</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ce qu'il ne faut PAS faire</strong></td>\n            <td><span class=\"kw-alerte\">AINS</span> — pas indiqués dans la sécheresse oculaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pivot pratique.</strong> Toujours préférer <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">larmes artificielles sans conservateurs</span> (les conservateurs comme le chlorure de benzalkonium aggravent la sécheresse à long terme). Les soins de paupières (chauffage + massage) sont la mesure non médicamenteuse la plus rentable, en particulier sur les sécheresses par dysfonctionnement meibomien (rosacée, blépharite chronique).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span></em></p>","frequence":0},{"id":"83-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","contenu":"<p>Trois familles de collyres très utilisées, avec des <strong><span class=\"kw-ci\">contre-indications</span> strictes</strong> en <span class=\"kw-chiffre\">première intention</span> sans avis ophtalmologique — en particulier <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">corticoïdes locaux</span> dont la prescription à l'aveugle sur un œil rouge est responsable de complications graves (perforation cornéenne sur <span class=\"kw-etio\">HSV</span>, glaucome cortico-induit, cataracte).</p>\n\n      <table >\n        <thead>\n          <tr><th>Famille</th><th>Indications</th><th><span class=\"kw-ci\">Contre-indications</span> / précautions</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Collyres anesthésiques</strong> (oxybuprocaïne, tétracaïne)</td>\n            <td>\n              Examen ophtalmologique ponctuel (LAF, ablation de CE, fluorescéine)<br>\n              Tonométrie<br>\n              Geste douloureux ambulatoire\n            </td>\n            <td>\n              <span class=\"kw-alerte\">JAMAIS en prescription prolongée ou répétée</span> ⚠️ — risque de <span class=\"kw-alerte\">perforation cornéenne</span> (toxicité directe de l'épithélium, abolition du réflexe de clignement, masquage de la douleur d'alerte)<br>\n              Usage médical hospitalier uniquement — pas de remise au patient\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Collyres antibiotiques</strong> (<span class=\"kw-ttt\">azithromycine</span>, <span class=\"kw-ttt\">ciprofloxacine</span>, <span class=\"kw-ttt\">tobramycine</span>, rifamycine, <span class=\"kw-ttt\">vancomycine</span> fortifiée, gentamycine, etc.)</td>\n            <td>\n              <strong>Conjonctivite <span class=\"kw-etio\">bactérienne</span> :</strong> uniquement <span class=\"kw-clinique\">si signe de gravité</span> (chémosis intense, atteinte cornéenne, immunodépression) ou échec du traitement par antiseptique ; ciblés CG+<br>\n              <strong>Kératite / <span class=\"kw-clinique\">abcès</span> de cornée :</strong> empirique (<span class=\"kw-ttt\">ciprofloxacine</span>, <span class=\"kw-ttt\">tobramycine</span>) si forme précoce ; <strong>collyres fortifiés horaires hospitaliers</strong> (<span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">amikacine</span> ou ceftazidime) si <span class=\"kw-clinique\">abcès</span> grave<br>\n              <strong>Conjonctivite à inclusion (<span class=\"kw-clinique\">Chlamydia</span>) :</strong> <span class=\"kw-ttt\">azithromycine</span> PO monodose<br>\n              <strong>Trachome :</strong> <span class=\"kw-ttt\">azithromycine</span> ou tétracyclines\n            </td>\n            <td>\n              <strong><span class=\"kw-ci\">Allergie</span></strong> au principe actif (collyres ATB = cause fréquente d'allergie de <span class=\"kw-def\">contact</span>)<br>\n              Conjonctivite <span class=\"kw-etio\">virale</span> non compliquée → <span class=\"kw-alerte\">pas d'ATB systématique</span> (résistances, allergisation, masquage d'<span class=\"kw-clinique\">évolution</span>)<br>\n              Conjonctivite <span class=\"kw-etio\">allergique</span> pure\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Collyres <span class=\"kw-ttt\">corticoïdes</span></strong> (<span class=\"kw-ttt\">dexaméthasone</span>, rimexolone, fluorométholone, etc.)</td>\n            <td>\n              <strong>Uvéite antérieure</strong> (couplés aux mydriatiques)<br>\n              <strong>Sclérite, épisclérite</strong> récidivante<br>\n              <strong>Conjonctivite <span class=\"kw-etio\">virale</span> sévère</strong> avec membranes (après ablation)<br>\n              <strong>Conjonctivite <span class=\"kw-etio\">allergique</span> intense</strong> (cure courte)<br>\n              <strong>Kérato-conjonctivite vernale / <span class=\"kw-etio\">atopique</span></strong> (en phase aiguë)<br>\n              <strong>Kératite stromale post-zostérienne / herpétique avec atteinte stromale disciforme</strong> (sous couverture antivirale)<br>\n              <strong>Postopératoire</strong> (<span class=\"kw-ttt\">chirurgie</span> de cataracte, greffe)\n            </td>\n            <td>\n              <strong>⚠️ <span class=\"kw-ci\">CI absolue</span> :</strong> <span class=\"kw-alerte\">kératite herpétique</span> (perforation cornéenne ; ulcère dendritique à la fluo = <span class=\"kw-etio\">HSV</span> jusqu'à preuve du contraire)<br>\n              <strong><span class=\"kw-ci\">CI relative</span> :</strong> tout œil rouge douloureux <span class=\"kw-clinique\">sans diagnostic précis</span> — écarter systématiquement HSV avant prescription<br>\n              <strong>Précautions au long cours :</strong> <span class=\"kw-def\">surveillance</span> du tonus oculaire (risque de <span class=\"kw-alerte\">glaucome cortico-induit</span>), du cristallin (risque de <span class=\"kw-alerte\">cataracte sous-capsulaire postérieure</span>), de la surface (surinfection, retard de cicatrisation)<br>\n              <strong><span class=\"kw-clinique\">Zona</span> ophtalmique :</strong> classiquement CI sauf indications restreintes (kératite immunologique, uvéite antérieure après avis ophtalmologique)<br>\n              <strong>Conjonctivite <span class=\"kw-etio\">virale</span> :</strong> attention — <span class=\"kw-clinique\">les</span> CTC <span class=\"kw-clinique\">prolongent le portage viral</span>, à réserver aux formes sévères\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Règle d'or QCM ⭐⭐⭐.</strong> Devant tout œil rouge douloureux non examiné par un ophtalmologue : <span class=\"kw-alerte\">PAS DE COLLYRE CTC</span>, <span class=\"kw-alerte\">PAS D'ANESTHÉSIQUE PROLONGÉ</span>. Si doute = avis ophtalmo en <span class=\"kw-alerte\">urgence</span>, LAF + fluorescéine pour écarter <span class=\"kw-etio\">HSV</span> avant toute <span class=\"kw-ttt\">corticothérapie</span> locale.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus · 322 — Décision thérapeutique personnalisée · 84 — Glaucome chronique</em></p>","frequence":3}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> l'<span class=\"kw-alerte\">œil rouge douloureux avec BAV</span> est une <span class=\"kw-alerte\">urgence ophtalmologique</span> imposant un avis spécialisé immédiat ; l'œil rouge sans BAV est rarement urgent.<br><strong>Endophtalmie postopératoire :</strong> <span class=\"kw-alerte\">hospitalisation en urgence</span>, <span class=\"kw-alerte\">pronostic sombre</span> — <span class=\"kw-ttt\">prélèvements + injections intravitréennes d'antibiotiques</span> sans délai.<br><strong><span class=\"kw-clinique\">Zona</span> ophtalmique :</strong> <span class=\"kw-ttt\">valaciclovir</span> per os à débuter dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">72 premières heures</span> de l'<span class=\"kw-clinique\">éruption</span>.<br><strong>1er geste :</strong> mesurer l'<span class=\"kw-clinique\">acuité visuelle</span> et examiner à la <span class=\"kw-imagerie\">lampe à fente</span> avec <span class=\"kw-imagerie\">test à la fluorescéine</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">conjonctivite</span>, <span class=\"kw-etio\">épisclérite</span>, <span class=\"kw-etio\">sécheresse oculaire</span>, <span class=\"kw-etio\">abcès de cornée</span> précoce et peu sévère sous <span class=\"kw-ttt\">antibiotiques topiques</span>.<br><strong>Avis / <span class=\"kw-alerte\">hospitalisation</span> ophtalmologique en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-alerte\">endophtalmie postopératoire</span>, <span class=\"kw-alerte\">uvéite postérieure</span>, <span class=\"kw-etio\">abcès de cornée</span> important (<span class=\"kw-ttt\">collyres ATB fortifiés horaires</span>).<br><strong>Consultation de médecine interne :</strong> <span class=\"kw-etio\">sclérite</span> (bilan étiologique dès le 1er épisode) et <span class=\"kw-etio\">uvéite</span> à enquête étiologique.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Baisse d'acuité visuelle</span> permanente associée à l'œil rouge</li><li><span class=\"kw-alerte\">Douleur profonde</span> ciliaire, insomniante (sclérite, uvéite)</li><li><span class=\"kw-clinique\">Hypopion</span> (niveau de pus en chambre antérieure)</li><li><span class=\"kw-radio\">Plage blanchâtre cornéenne</span> avec prise de fluorescéine = <span class=\"kw-etio\">abcès de cornée</span></li><li><span class=\"kw-radio\">Ulcère dendritique</span> à la fluorescéine = <span class=\"kw-etio\">kératite herpétique</span></li><li><span class=\"kw-clinique\">Contexte postopératoire</span> récent + œil rouge douloureux avec BAV = <span class=\"kw-alerte\">endophtalmie</span></li><li><span class=\"kw-clinique\">Hyalite</span> ou foyer <span class=\"kw-etio\">inflammatoire</span> au <span class=\"kw-imagerie\">fond d'œil</span> = <span class=\"kw-etio\">uvéite postérieure</span></li><li>Rougeur en secteur ne disparaissant PAS au collyre vasoconstricteur = <span class=\"kw-etio\">sclérite</span></li></ul>","principes":"<p>La conduite découle du couple <span class=\"kw-clinique\">douleur</span> / <span class=\"kw-clinique\">BAV</span> : œil rouge sans BAV (bénin) versus avec BAV (<span class=\"kw-alerte\">urgence</span> ophtalmologique).</p><p><strong>Œil rouge SANS BAV (bénin, ambulatoire)</strong></p><p>Réadresser en <span class=\"kw-alerte\">urgence</span> si apparition d'une <span class=\"kw-alerte\">BAV permanente</span> ou d'une <span class=\"kw-clinique\">douleur profonde</span>.</p><ul><li><span class=\"kw-etio\">Conjonctivite bactérienne</span> : <span class=\"kw-ttt\">lavages au sérum physiologique</span>, <span class=\"kw-ttt\">collyre antiseptique</span> 4 à 6 fois/jour, <span class=\"kw-ttt\">hygiène des mains</span> ; <span class=\"kw-ci\">pas d'antibiotique systématique</span> sans <span class=\"kw-alerte\">signe de gravité</span></li><li><span class=\"kw-etio\">Conjonctivite virale</span> (<span class=\"kw-etio\">adénovirus</span>) : traitement symptomatique, <span class=\"kw-ci\">corticoïdes réservés aux formes sévères</span> (prolongent le portage <span class=\"kw-etio\">viral</span>)</li><li><span class=\"kw-etio\">Conjonctivite allergique</span> : <span class=\"kw-ttt\">anti-H1</span>, <span class=\"kw-ttt\">antidégranulant mastocytaire (cromone)</span>, éviction de l'allergène</li><li><span class=\"kw-etio\">Épisclérite</span> : rougeur disparaissant au collyre vasoconstricteur (<span class=\"kw-ttt\">phényléphrine</span>), pas de bilan au 1er épisode</li><li><span class=\"kw-etio\">Sclérite</span> : <span class=\"kw-ttt\">AINS par voie générale</span> en 1re intention + bilan étiologique (médecine interne) ; <span class=\"kw-ttt\">corticothérapie systémique</span> si forme grave</li></ul><p><strong>Œil rouge AVEC BAV (<span class=\"kw-alerte\">urgence</span> ophtalmologique)</strong></p><ul><li><span class=\"kw-etio\">Kératite / abcès de cornée</span> : <span class=\"kw-ttt\">antibiotiques topiques</span> en ambulatoire si peu sévère, <span class=\"kw-ttt\">collyres ATB fortifiés horaires</span> en <span class=\"kw-alerte\">hospitalisation</span> si <span class=\"kw-clinique\">abcès</span> important, après <span class=\"kw-ttt\">prélèvement à l'écouvillon</span></li><li><span class=\"kw-etio\">Kératite herpétique</span> : <span class=\"kw-ttt\">antiviraux</span> (<span class=\"kw-ttt\">valaciclovir</span>/<span class=\"kw-ttt\">aciclovir</span> per os ou topiques) — <span class=\"kw-ci\">contre-indication absolue aux corticoïdes locaux</span></li><li><span class=\"kw-etio\">Uvéite antérieure</span> : <span class=\"kw-ttt\">collyres mydriatiques (atropine)</span> pour lâcher <span class=\"kw-clinique\">les</span> synéchies + <span class=\"kw-ttt\">collyres corticoïdes</span> + traitement de l'étiologie</li><li><span class=\"kw-etio\">Uvéite postérieure</span> : <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-bio\">sérologie VIH</span>, <span class=\"kw-ttt\">ponction</span> de chambre antérieure, traitement par voie générale selon l'étiologie ; toxoplasmose → <span class=\"kw-ttt\">pyriméthamine + sulfadiazine</span></li><li><span class=\"kw-etio\">Endophtalmie postopératoire</span> : <span class=\"kw-ttt\">injections intravitréennes (vancomycine + ceftazidime)</span> + <span class=\"kw-ttt\">antibiothérapie systémique (lévofloxacine + imipénème)</span> ± <span class=\"kw-ttt\">vitrectomie</span></li></ul><p><strong>Règles d'or des collyres</strong></p><ul><li><span class=\"kw-ttt\">Anesthésiques topiques</span> (oxybuprocaïne, tétracaïne) : usage diagnostique ponctuel uniquement — <span class=\"kw-ci\">jamais en prescription répétée ou prolongée</span> (risque de <span class=\"kw-alerte\">perforation cornéenne</span>)</li><li><span class=\"kw-ttt\">Corticoïdes locaux</span> : <span class=\"kw-ci\">contre-indiqués devant tout œil rouge avant d'avoir écarté une kératite herpétique</span> et un <span class=\"kw-clinique\">abcès</span> de cornée</li><li><span class=\"kw-ttt\">Antibiotiques</span> : ciblés sur <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">cocci Gram+</span> dans les conjonctivites bactériennes graves, pas de prescription systématique</li></ul>","suivi":"<p><strong>Kératite herpétique :</strong> risque de <span class=\"kw-etio\">récidives</span> → <span class=\"kw-ttt\">prophylaxie antiherpétique orale</span> si <span class=\"kw-chiffre\">plus de 6 récurrences/an</span>.<br><strong>Uvéite antérieure :</strong> surveiller l'apparition d'une <span class=\"kw-etio\">cataracte</span> et d'un <span class=\"kw-etio\">glaucome</span> (inflammation prolongée + collyres <span class=\"kw-ttt\">corticoïdes</span> répétés).<br><strong>Sclérite / épisclérite :</strong> bilan étiologique si <span class=\"kw-clinique\">récidive</span> ; surveiller la <span class=\"kw-alerte\">nécrose sclérale</span>.<br><strong>Toxoplasmose oculaire :</strong> <span class=\"kw-etio\">récidives</span> possibles tout au long de la vie à partir de la cicatrice rétinienne.<br><strong>Sécheresse oculaire :</strong> chronique — <span class=\"kw-ttt\">substituts lacrymaux</span> et éviction des facteurs irritants.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Œil rouge — Pivot d'orientation : existe-t-il une baisse d'acuité visuelle (BAV) ?","detail":"<h4>CAT — Œil rouge (infections et inflammations oculaires) — Devant un œil rouge, la BAV et la douleur orientent le degré d'<span class=\"kw-alerte\">urgence</span> et la structure atteinte</h4>","branches":[{"to":"q-douleur","label":"Pas de BAV","color":"green"},{"to":"q-structure","label":"BAV présente — urgence ophtalmologique","color":"red"}]},{"id":"q-douleur","kind":"decision","label":"Type de douleur ? (œil rouge SANS BAV) — Gêne superficielle versus douleur profonde / en secteur","branches":[{"to":"t-conjonctivite","label":"Gêne superficielle « grains de sable » / œil rouge indolore","color":"green"},{"to":"t-sclerite","label":"Douleur en secteur ou profonde ciliaire","color":"amber"}]},{"id":"t-conjonctivite","kind":"terminal","label":"Œil rouge bénin — ambulatoire — Conjonctivite, hémorragie sous-conjonctivale","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Sensation de grains de sable</span>, <span class=\"kw-clinique\">sécrétions</span>, rougeur diffuse ; <span class=\"kw-clinique\">pas de BAV permanente</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Lavages au sérum physiologique</span> + <span class=\"kw-ttt\">collyre antiseptique</span> + <span class=\"kw-ttt\">hygiène des mains</span></li><li><span class=\"kw-ci\">Pas d'antibiotique systématique</span> sans <span class=\"kw-alerte\">signe de gravité</span> ; <span class=\"kw-ci\">corticoïdes réservés aux formes sévères</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Réadresser si <span class=\"kw-alerte\">BAV permanente</span> ou douleur = atteinte cornéenne (kératoconjonctivite)</li></ul>"},{"id":"t-sclerite","kind":"terminal","label":"Épisclérite / sclérite — ambulatoire — Œil rouge douloureux SANS BAV","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Épisclérite</span> : rougeur en secteur, douleur modérée, <span class=\"kw-clinique\">disparaît au collyre vasoconstricteur</span> (<span class=\"kw-ttt\">phényléphrine</span>)</li><li><span class=\"kw-etio\">Sclérite</span> : <span class=\"kw-alerte\">douleur ciliaire insomniante</span>, <span class=\"kw-clinique\">ne disparaît pas au vasoconstricteur</span></li></ul><h4>Conduite</h4><ul><li>Épisclérite : pas de bilan au 1er épisode</li><li>Sclérite : <span class=\"kw-ttt\">AINS par voie générale</span> en 1re intention + <span class=\"kw-bio\">bilan étiologique</span> (médecine interne) dès le 1er épisode ; <span class=\"kw-ttt\">corticothérapie systémique</span> si forme grave</li></ul>"},{"id":"q-structure","kind":"decision","label":"Structure atteinte ? (œil rouge douloureux AVEC BAV) — Urgence ophtalmologique — orienter selon cornée / segment antérieur / segment postérieur / contexte postopératoire","branches":[{"to":"t-keratite","label":"Cornée : fluorescéine + (ulcère / abcès)","color":"amber"},{"to":"t-uveite-ant","label":"Segment antérieur : Tyndall, précipités, myosis","color":"amber"},{"to":"t-uveite-post","label":"Segment postérieur : hyalite, foyer au FO","color":"red"},{"to":"t-endophtalmie","label":"Contexte postopératoire / injection intravitréenne","color":"red"}]},{"id":"t-keratite","kind":"terminal","label":"Kératite / abcès de cornée — urgence — Test à la fluorescéine décisif","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-radio\">Ulcère dendritique</span> = <span class=\"kw-etio\">kératite herpétique</span> ; <span class=\"kw-radio\">ulcère + plage blanchâtre ± hypopion</span> = <span class=\"kw-etio\">abcès de cornée</span></li><li><span class=\"kw-ttt\">Prélèvement à l'écouvillon</span> de l'<span class=\"kw-clinique\">abcès</span> avant traitement</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-clinique\">Abcès</span> : <span class=\"kw-ttt\">antibiotiques topiques</span> en ambulatoire si peu sévère, <span class=\"kw-ttt\">collyres ATB fortifiés horaires</span> en <span class=\"kw-alerte\">hospitalisation</span> si <span class=\"kw-clinique\">abcès</span> important</li><li>Herpès : <span class=\"kw-ttt\">antiviraux</span> (<span class=\"kw-ttt\">valaciclovir</span> / <span class=\"kw-ttt\">aciclovir</span>) — <span class=\"kw-ci\">corticoïdes locaux contre-indiqués</span> (risque de <span class=\"kw-alerte\">perforation cornéenne</span>)</li></ul>"},{"id":"t-uveite-ant","kind":"terminal","label":"Uvéite antérieure — avis ophtalmologique — Tyndall, précipités rétrocornéens, myosis","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Pupille en myosis</span>, <span class=\"kw-clinique\">Tyndall</span>, <span class=\"kw-clinique\">précipités rétrocornéens</span>, <span class=\"kw-clinique\">synéchies postérieures</span> ; <span class=\"kw-imagerie\">fond d'œil systématique</span></li></ul><h4>Paraclinique</h4><ul><li>Bilan étiologique : <span class=\"kw-bio\">HLA-B27</span>, <span class=\"kw-bio\">NFS-CRP-VS</span>, <span class=\"kw-bio\">enzyme de conversion de l'angiotensine</span>, <span class=\"kw-bio\">TPHA-VDRL</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Collyres mydriatiques (atropine)</span> pour lâcher <span class=\"kw-clinique\">les</span> synéchies + <span class=\"kw-ttt\">collyres corticoïdes</span> + traitement de l'étiologie</li></ul>"},{"id":"t-uveite-post","kind":"terminal","label":"Uvéite postérieure — hospitalisation urgente — Hyalite, foyer au fond d'œil","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation en urgence</span>, <span class=\"kw-bio\">sérologie VIH</span>, <span class=\"kw-ttt\">ponction de chambre antérieure</span> (<span class=\"kw-bio\">PCR</span> <span class=\"kw-etio\">HSV</span> / VZV / CMV, toxoplasmose)</li></ul><h4>Traitement</h4><ul><li>Traitement par voie générale en <span class=\"kw-alerte\">urgence</span> selon l'étiologie ; <span class=\"kw-etio\">toxoplasmose</span> (la plus fréquente) → <span class=\"kw-ttt\">pyriméthamine + sulfadiazine</span> si <span class=\"kw-alerte\">menace</span> pour l'acuité visuelle</li></ul>"},{"id":"t-endophtalmie","kind":"terminal","label":"Endophtalmie postopératoire — urgence vitale oculaire — Contexte postopératoire / injection intravitréenne","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV quasi totale</span> + <span class=\"kw-alerte\">douleur intense</span> du côté opéré, <span class=\"kw-clinique\">hypopion</span>, <span class=\"kw-clinique\">hyalite</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation en urgence</span> ; <span class=\"kw-ttt\">prélèvements (ponction du vitré ou de l'humeur aqueuse)</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Injections intravitréennes d'antibiotiques (vancomycine + ceftazidime)</span> + <span class=\"kw-ttt\">ATB systémique (lévofloxacine + imipénème)</span> ± <span class=\"kw-ttt\">vitrectomie</span> ; <span class=\"kw-alerte\">pronostic sombre</span></li></ul>"}]},"cards":[{"i":"3327ae47fcdd","n":83,"o":"83-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quel est l'intérêt du test à la fluorescéine dans le diagnostic d'une infection ou inflammation oculaire ?","a":"<p>Le test à la fluorescéine est <strong>systématique devant toute kératalgie</strong> et permet de :</p><ul><li>Mettre en évidence un <strong>ulcère dendritique</strong>, évocateur d'une infection à <strong>HSV</strong> (Herpes Simplex Virus).</li><li>Révéler des lésions <strong>ponctuées superficielles</strong>, signant une <strong>sécheresse oculaire</strong> ou une infection à <strong>adénovirus</strong>.</li><li>Détecter le <strong>signe de Seidel</strong>, indiquant une <strong>perforation cornéenne</strong>.</li></ul>"},{"i":"34a5abb3bb57","n":83,"o":"83-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Comment la sémiologie de la douleur oculaire permet-elle d'orienter vers une étiologie spécifique ?","a":"<ul><li>Une douleur <strong>superficielle en « grains de sable »</strong> évoque une <strong>conjonctivite</strong>.</li><li>Une douleur <strong>profonde, ciliaire, insomniante</strong> suggère une <strong>sclérite</strong> ou une <strong>uvéite</strong>.</li><li>Une douleur <strong>intense associée à une photophobie et un blépharospasme</strong> doit faire penser à une <strong>kératite</strong> ou un <strong>abcès cornéen</strong>.</li></ul>"},{"i":"3c7101688164","n":83,"o":"83-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quelles caractéristiques des sécrétions oculaires orientent vers une étiologie virale ou bactérienne ?","a":"<ul><li>Des sécrétions <strong>mucopurulentes en « poils de pinceau »</strong> sont caractéristiques d'une étiologie <strong>bactérienne</strong>.</li><li>Des sécrétions <strong>claires</strong> orientent vers une étiologie <strong>virale</strong> ou <strong>allergique</strong>.</li><li>L'<strong>absence de sécrétions</strong> est typique d'une <strong>uvéite</strong> ou d'une <strong>sclérite</strong>.</li></ul>"},{"i":"3e33cf1b22cc","n":83,"o":"83-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quels sont les éléments clés à inspecter lors de l'examen clinique de l'œil et de ses annexes en cas d'infection ou d'inflammation oculaire ?","a":"<p>Lors de l'inspection externe, il faut examiner :</p><ul><li>Les <strong>paupières</strong> (recherche d'œdème, vésicules herpétiques ou zona, ectropion, eczéma atopique).</li><li>La <strong>conjonctive</strong> (hyperhémie diffuse ou localisée, chémosis, hémorragie sous-conjonctivale).</li><li>La présence et l'aspect des <strong>sécrétions</strong> (quantité, latéralité).</li><li>La palpation d'une <strong>adénopathie prétragienne</strong>, signe en faveur d'une cause infectieuse virale ou à Chlamydia.</li></ul>"},{"i":"b0f8124787f2","n":83,"o":"83-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quand faut-il réaliser un fond d'œil et mesurer le tonus oculaire en cas de suspicion d'infection ou d'inflammation oculaire ?","a":"<ul><li>Un <strong>fond d'œil</strong> est <strong>systématique si une uvéite ou une endophtalmie est suspectée</strong>, pour rechercher une hyalite, un foyer choriorétinien ou une papillite.</li><li>La mesure du <strong>tonus oculaire</strong> à l'aide d'un tonomètre est importante, car une <strong>hypertonie</strong> peut évoquer une <strong>uvéite herpétique</strong>, un syndrome de <strong>Posner-Schlossman</strong>, ou un <strong>glaucome aigu par fermeture de l'angle</strong>.</li></ul>"},{"i":"c4fb2ec0527c","n":83,"o":"83-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique","q":"Quels sont les quatre signes cliniques cardinaux à rechercher à l'interrogatoire pour orienter le diagnostic d'une infection ou inflammation oculaire ?","a":"<p>Les quatre signes cardinaux à rechercher sont :</p><ul><li>La <strong>douleur</strong>.</li><li>La <strong>baisse d'acuité visuelle</strong> (BAV).</li><li>La <strong>rougeur oculaire</strong>.</li><li>La présence de <strong>sécrétions</strong>.</li></ul>"},{"i":"4faf33c93e9c","n":83,"o":"83-12","u":"Prise en charge","t":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","q":"Quelle est la contre-indication absolue des collyres corticoïdes ?","a":"<p>La contre-indication <strong>absolue</strong> des collyres corticoïdes est la <strong>kératite herpétique</strong> (risque de perforation cornéenne). Toute lésion de type <strong>ulcère dendritique</strong> à la fluorescéine doit faire éliminer une kératite herpétique avant toute prescription de corticoïdes.</p>"},{"i":"63b4340b919d","n":83,"o":"83-12","u":"Prise en charge","t":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","q":"Quelles sont les indications des collyres anesthésiques (oxybuprocaïne, tétracaïne) en ophtalmologie ?","a":"<p>Les collyres anesthésiques sont indiqués pour :</p><ul><li>L'<strong>examen ophtalmologique ponctuel</strong> (lampe à fente, ablation d'un corps étranger, pose de fluorescéine).</li><li>La <strong>tonométrie</strong>.</li><li>Tout <strong>geste douloureux ambulatoire</strong> sur l'œil.</li></ul>"},{"i":"68d974b2d74a","n":83,"o":"83-12","u":"Prise en charge","t":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","q":"Quelles sont les contre-indications à l'utilisation des collyres antibiotiques ?","a":"<p>Les collyres antibiotiques sont contre-indiqués en cas d'<strong>allergie au principe actif</strong>.</p><p>Ils ne sont <strong>pas systématiques</strong> et doivent être évités en cas de <strong>conjonctivite virale non compliquée</strong> ou de <strong>conjonctivite allergique pure</strong> (risques de résistances, allergisation, masquage d'évolution).</p>"},{"i":"a1f518e304f5","n":83,"o":"83-12","u":"Prise en charge","t":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","q":"Quelles précautions prendre lors de la prescription de collyres corticoïdes au long cours ?","a":"<p>Lors d'une prescription de collyres corticoïdes au long cours, une surveillance est nécessaire en raison des risques de complications :</p><ul><li><strong>Glaucome cortico-induit</strong> (surveillance du tonus oculaire).</li><li><strong>Cataracte sous-capsulaire postérieure</strong> (surveillance du cristallin).</li><li><strong>Surinfection</strong> et <strong>retard de cicatrisation</strong> (surveillance de la surface oculaire).</li></ul><p>En cas de <strong>zona ophtalmique</strong>, ils sont classiquement contre-indiqués, sauf indications très restreintes après avis ophtalmologique (kératite immunologique, uvéite antérieure).</p>"},{"i":"a453a5702b18","n":83,"o":"83-12","u":"Prise en charge","t":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","q":"Quelles sont les indications des collyres corticoïdes en ophtalmologie ?","a":"<p>Les collyres corticoïdes sont indiqués pour :</p><ul><li>L'<strong>uvéite antérieure</strong> (couplés aux mydriatiques).</li><li>La <strong>sclérite</strong> et l'<strong>épisclérite récidivante</strong>.</li><li>La <strong>conjonctivite virale sévère avec membranes</strong> (après ablation).</li><li>La <strong>conjonctivite allergique intense</strong> (cure courte) et la <strong>kérato-conjonctivite vernale/atopique</strong> (en phase aiguë).</li><li>La <strong>kératite stromale post-zostérienne/herpétique avec atteinte stromale disciforme</strong> (sous couverture antivirale).</li><li>Le <strong>postopératoire</strong> (chirurgie de cataracte, greffe).</li></ul>"},{"i":"ce7642acd25c","n":83,"o":"83-12","u":"Prise en charge","t":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","q":"Dans quelles situations les collyres antibiotiques sont-ils indiqués en ophtalmologie ?","a":"<p>Les collyres antibiotiques sont indiqués pour :</p><ul><li>Les <strong>conjonctivites bactériennes</strong>, uniquement en cas de <strong>signes de gravité</strong> (chémosis intense, atteinte cornéenne, immunodépression) ou d'échec d'un traitement antiseptique.</li><li>Les <strong>kératites ou abcès de cornée</strong> : traitement empirique (ciprofloxacine, tobramycine) si forme précoce, ou collyres fortifiés horaires hospitaliers (vancomycine + amikacine ou ceftazidime) si abcès grave.</li></ul><p>L'<strong>azithromycine orale</strong> est indiquée pour les conjonctivites à inclusion (Chlamydia) et le trachome.</p>"},{"i":"d5c7470c0b30","n":83,"o":"83-12","u":"Prise en charge","t":"Connaître les indications et contre-indications des collyres anesthésiques, antibiotiques et corticoïdes","q":"Quelles sont les contre-indications et précautions d'emploi des collyres anesthésiques (oxybuprocaïne, tétracaïne) ?","a":"<p>Il est <strong>JAMAIS</strong> indiqué de prescrire des collyres anesthésiques de manière <strong>prolongée ou répétée</strong> en raison du risque de <strong>perforation cornéenne</strong> (toxicité directe de l'épithélium, abolition du réflexe de clignement, masquage de la douleur).</p><p>Leur usage doit être <strong>médical hospitalier uniquement</strong> et ils ne doivent pas être remis au patient.</p>"},{"i":"0cf220c87544","n":83,"o":"83-2","u":"Prise en charge","t":"Connaître la conduite à tenir devant un œil rouge douloureux sans baisse d’acuité visuelle","q":"Comment différencier une épisclérite d'une sclérite et quel est le test diagnostique clé ?","a":"<p>L'<strong>épisclérite</strong> est caractérisée par une <strong>rougeur en secteur</strong>, une douleur modérée qui <strong>disparaît à l'instillation d'un vasoconstricteur</strong> (p. ex., phényléphrine), et l'absence de baisse d'acuité visuelle.</p><p>La <strong>sclérite</strong> se manifeste par une <strong>douleur ciliaire intense et insomniante</strong>, aggravée par la mobilisation du globe. La rougeur peut être plane ou nodulaire et, crucialement, <strong>ne disparaît pas au vasoconstricteur</strong>.</p><p>Le <strong>test discriminant clé</strong> au lit du patient est l'instillation d'un <strong>vasoconstricteur</strong> (chlorhydrate de phényléphrine, néosynéphrine) : la rougeur disparaît dans l'épisclérite et persiste dans la sclérite.</p>"},{"i":"1c74c7b9cbb7","n":83,"o":"83-2","u":"Prise en charge","t":"Connaître la conduite à tenir devant un œil rouge douloureux sans baisse d’acuité visuelle","q":"Comment distinguer cliniquement une conjonctivite virale d'une conjonctivite allergique et quelle est leur prise en charge respective ?","a":"<p>La <strong>conjonctivite virale</strong> (adénovirus) se manifeste par :</p><ul><li>Une hyperhémie avec des <strong>hémorragies conjonctivales</strong>.</li><li>Des sécrétions <strong>claires</strong>.</li><li>Une <strong>adénopathie prétragienne sensible</strong>.</li><li>Elle survient souvent dans un <strong>contexte épidémique</strong>.</p><p>La prise en charge est <strong>symptomatique</strong> (lavages, mouillants). Les <strong>corticoïdes locaux</strong> sont réservés aux formes sévères avec membranes (ils prolongent le portage viral). Une <strong>éviction scolaire/professionnelle</strong> est recommandée.</p><p>La <strong>conjonctivite allergique</strong> présente :</p><ul><li>Un <strong>prurit intense</strong>.</li><li>Une atteinte <strong>bilatérale</strong>.</li><li>Un <strong>chémosis blanc laiteux</strong>.</li><li>Souvent une <strong>rhinite associée</strong>, avec un caractère saisonnier ou per-annuel.</p><p>Le traitement inclut des <strong>anti-H1 par voie orale de 2ᵉ génération</strong>, un <strong>collyre anti-H1 et/ou antidégranulant mastocytaire</strong> (cromone). Des <strong>corticoïdes en cure courte</strong> peuvent être utilisés si l'intensité est forte. L'<strong>éviction de l'allergène</strong> et un bilan allergologique sont nécessaires.</p>"},{"i":"3ed32f449fc6","n":83,"o":"83-2","u":"Prise en charge","t":"Connaître la conduite à tenir devant un œil rouge douloureux sans baisse d’acuité visuelle","q":"Comment doit-on aborder initialement un œil rouge douloureux sans baisse d'acuité visuelle ?","a":"<p>Un œil rouge douloureux sans baisse d'acuité visuelle est une situation moins urgente qu'avec une baisse d'acuité. L'orientation diagnostique repose sur :</p><ul><li>La <strong>latéralité</strong> (uni- ou bilatérale) de l'atteinte.</li><li>La présence et le type de <strong>sécrétions</strong> (claires, mucopurulentes).</li><li>La <strong>topographie</strong> de la rougeur (diffuse, locale).</li></ul>"},{"i":"7ce58db2da16","n":83,"o":"83-2","u":"Prise en charge","t":"Connaître la conduite à tenir devant un œil rouge douloureux sans baisse d’acuité visuelle","q":"Quelles sont les caractéristiques cliniques discriminantes d'une conjonctivite bactérienne aiguë et quelle est sa prise en charge initiale ?","a":"<p>La conjonctivite bactérienne aiguë se caractérise par :</p><ul><li>Une <strong>hyperhémie diffuse</strong> prédominant dans le cul-de-sac inférieur.</li><li>Des <strong>sécrétions mucopurulentes</strong> en « poils de pinceau » au réveil.</li><li>Elle est souvent <strong>unilatérale puis bilatérale</strong>.</p><p>La prise en charge initiale comprend :</p><ul><li>Des <strong>lavages</strong> au sérum physiologique.</li><li>Un <strong>collyre antiseptique</strong> 4 à 6 fois par jour.</li><li>Des <strong>antibiotiques</strong> ciblés sur les cocci Gram positifs si signes de gravité ou résistance.</li><li>Une <strong>hygiène des mains</strong> systématique.</li></ul>"},{"i":"9906ef496e62","n":83,"o":"83-2","u":"Prise en charge","t":"Connaître la conduite à tenir devant un œil rouge douloureux sans baisse d’acuité visuelle","q":"Quelle est la prise en charge d'une épisclérite et d'une sclérite, notamment concernant le bilan étiologique ?","a":"<p>Une <strong>épisclérite</strong> est souvent <strong>idiopathique</strong>. Le traitement repose sur des <strong>anti-inflammatoires non stéroïdiens (AINS) locaux</strong> ou des <strong>corticoïdes locaux</strong>. <strong>Aucun bilan</strong> n'est nécessaire au premier épisode. En cas de <strong>récidive</strong>, un bilan étiologique pour une potentiel sclérite doit être envisagé.</p><p>Une <strong>sclérite</strong> nécessite un <strong>bilan étiologique dès le premier épisode</strong> (consultation de médecine interne) en raison de la potentielle association à une maladie systémique. Le traitement de première intention est l'administration d'<strong>AINS par voie orale</strong>. Des <strong>corticoïdes</strong> ou des <strong>immunosuppresseurs</strong> sont indiqués en cas de forme grave (nécrose sclérale, baisse d'acuité visuelle).</p>"},{"i":"bb22220efac9","n":83,"o":"83-2","u":"Prise en charge","t":"Connaître la conduite à tenir devant un œil rouge douloureux sans baisse d’acuité visuelle","q":"Quelle est la particularité clinique d'une hémorragie sous-conjonctivale et quel est le bilan à réaliser ?","a":"<p>L'hémorragie sous-conjonctivale se présente comme une <strong>nappe rouge vif indolore</strong>. Elle peut être spontanée ou post-traumatique, et l'acuité visuelle est conservée.</p><p>Il n'y a <strong>aucun traitement spécifique</strong> pour l'hémorragie elle-même. Le bilan vise à rechercher une cause sous-jacente :</p><ul><li><strong>Hypertension artérielle</strong>.</li><li>Prise d'<strong>anticoagulants</strong>.</li><li><strong>Trouble de l'hémostase</strong>.</li><li>Antécédent de <strong>traumatisme</strong>.</li></ul>"},{"i":"55ad79853f80","n":83,"o":"83-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une hémorragie sous conjonctivale","q":"Quelles sont les principales étiologies à rechercher devant une hémorragie sous-conjonctivale ?","a":"<ul><li><strong>Idiopathique</strong> (cause la plus fréquente), souvent liée à un effort à glotte fermée (toux, éternuement, vomissement, Valsalva).</li><li><strong>Traumatique</strong> (traumatisme oculaire ou crânien).</li><li><strong>Hypertension artérielle (HTA)</strong>, à dépister systématiquement, surtout en cas de récidive.</li><li>Prise d'<strong>anticoagulants ou anti-agrégants</strong> (AVK, AOD, héparine, aspirine) avec vérification de l'INR/ratios si nécessaire.</li><li><strong>Troubles de l’hémostase</strong> (thrombopénie, hémopathie, déficit en facteurs de coagulation).</li></ul>"},{"i":"a08f2267b1b8","n":83,"o":"83-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une hémorragie sous conjonctivale","q":"Quelle est l'évolution habituelle et le traitement d'une hémorragie sous-conjonctivale ?","a":"<p>L'hémorragie sous-conjonctivale évolue vers une <strong>résorption spontanée en 10 à 15 jours</strong>, passant par des variations chromatiques (rouge vif → violet → jaune). <strong>Aucun traitement local n'accélère la résorption</strong>, et <strong>aucun traitement étiologique local</strong> n'est nécessaire. L'action principale est l'enquête étiologique.</p>"},{"i":"e5499016828b","n":83,"o":"83-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une hémorragie sous conjonctivale","q":"Quelles sont les modalités du diagnostic positif d'une hémorragie sous-conjonctivale et le besoin en examens complémentaires ?","a":"<p>Le diagnostic positif d'une hémorragie sous-conjonctivale est <strong>exclusivement clinique</strong>, réalisé par simple <strong>inspection</strong>. <strong>Aucun examen complémentaire</strong> n'est requis pour confirmer le diagnostic en lui-même.</p>"},{"i":"ee341db75be3","n":83,"o":"83-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une hémorragie sous conjonctivale","q":"Comment se présente cliniquement une hémorragie sous-conjonctivale typique chez l'adulte sain ?","a":"<p>Elle se manifeste par une <strong>nappe ou plage rouge vif homogène</strong> sous la conjonctive bulbaire, le plus souvent <strong>unilatérale</strong> et présentant des <strong>bords nets</strong>. Elle est caractérisée par l'<strong>absence de douleur</strong>, d'<strong>aucun symptôme de baisse d'acuité visuelle (BAV)</strong> et l'<strong>absence de sécrétions</strong>.</p>"},{"i":"1d57f9937609","n":83,"o":"83-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une conjonctivite","q":"Comment doit être caractérisée la douleur oculaire dans le diagnostic d'une conjonctivite ?","a":"<p>La douleur oculaire associée à une conjonctivite est de type <strong>superficielle</strong>. Elle se décrit généralement comme une <strong>sensation de corps étranger</strong>, des <strong>grains de sable</strong>, une <strong>brûlure</strong> ou un <strong>prurit</strong>.</p>"},{"i":"539f46cc7535","n":83,"o":"83-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une conjonctivite","q":"Quelles sont les principales catégories étiologiques des conjonctivites à considérer pour le diagnostic étiologique ?","a":"<p>Pour le diagnostic étiologique, les conjonctivites sont principalement regroupées en trois catégories :</p><ul><li>Les formes <strong>infectieuses</strong> (bactériennes, virales, ou chroniques à <em>Chlamydia</em>)</li><li>Les formes <strong>inflammatoires/allergiques</strong> (saisonnière, vernale, atopique, de contact)</li><li>La <strong>sécheresse oculaire</strong></li></ul>"},{"i":"88135cf9239d","n":83,"o":"83-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une conjonctivite","q":"Quels sont les signes cliniques caractéristiques de l'œil rouge dans le diagnostic d'une conjonctivite ?","a":"<p>L'œil rouge dans la conjonctivite se manifeste par une <strong>hyperhémie conjonctivale diffuse</strong>. Il n'y a <strong>pas de cercle périkératique</strong>, dont la présence orienterait vers une atteinte intra-oculaire.</p>"},{"i":"8d9dd8d90749","n":83,"o":"83-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une conjonctivite","q":"Comment définir cliniquement une conjonctivite ?","a":"<p>La conjonctivite est une inflammation de la conjonctive qui se présente cliniquement comme un <strong>œil rouge douloureux SANS baisse d'acuité visuelle</strong> (BAV).</p><p>La BAV, si présente, doit être uniquement une <strong>gêne transitoire par sécrétions</strong>, améliorée par le clignement ou le lavage. Une BAV permanente associée à la douleur doit faire suspecter une atteinte cornéenne associée.</p>"},{"i":"55166a3a5980","n":83,"o":"83-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épisclérite, une sclérite","q":"Quand réalise-t-on un bilan étiologique devant une épisclérite ou une sclérite ?","a":"<p>Devant une <strong>épisclérite</strong>, un bilan étiologique n'est pas nécessaire lors du <strong>premier épisode</strong>. Il devient obligatoire si l'épisclérite est <strong>récidivante</strong>. Pour une <strong>sclérite</strong>, un bilan étiologique approfondi (incluant une consultation en médecine interne) est <strong>obligatoire dès le premier épisode</strong> en raison de son association fréquente à des maladies systémiques.</p>"},{"i":"5b81b69bb521","n":83,"o":"83-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épisclérite, une sclérite","q":"Comment différencier une épisclérite d'une sclérite à l'examen clinique, notamment concernant la douleur et la rougeur ?","a":"<p>La <strong>douleur</strong> est un discriminant clé : elle est modérée dans l'épisclérite, tandis que la sclérite provoque des douleurs ciliaires importantes, insomniantes, irradiant autour de l'orbite, et aggravées par la mobilisation du globe. Concernant la <strong>rougeur</strong>, l'épisclérite est le plus souvent en secteur, alors que la sclérite peut être plane ou nodulaire, en secteur ou diffuse.</p>"},{"i":"ad8d72188e5f","n":83,"o":"83-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épisclérite, une sclérite","q":"Quel est l'intérêt du test au vasoconstricteur (néosynéphrine) dans le diagnostic différentiel entre épisclérite et sclérite ?","a":"<p>Le test au vasoconstricteur (ex: <strong>chlorhydrate de phényléphrine ou néosynéphrine</strong>) est un discriminant majeur. Si la rougeur <strong>disparaît</strong> après l'instillation d'une goutte de vasoconstricteur, il s'agit d'une <strong>épisclérite</strong> (le processus inflammatoire est superficiel et réagit au VASO). Si la rougeur <strong>persiste</strong>, il s'agit d'une <strong>sclérite</strong> (l'inflammation est plus profonde).</p>"},{"i":"bd5971241e58","n":83,"o":"83-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épisclérite, une sclérite","q":"Quelles sont les principales étiologies des sclérites à rechercher lors du bilan étiologique ?","a":"<p>Les sclérites sont souvent associées à des maladies systémiques. Les principales étiologies comprennent :<ul><li><strong>Articulaires</strong> : Spondylarthropathies (SpA), Polyarthrite Rhumatoïde (PR), Lupus Érythémateux Disséminé (LED).</li><li><strong>Vasculaires</strong> : Polyangéite noueuse (PAN), Granulomatose avec Polyangéite (GPA ou Wegener), Cryoglobulinémie, Behçet (plus rare).</li><li><strong>Digestives</strong> : Maladies Inflammatoires Chroniques de l'Intestin (MICI).</li><li><strong>Cutanée</strong> : Psoriasis.</li><li><strong>Infectieuses</strong> : Tuberculose, Herpès/Zona, Borréliose, infection locale à pyocyanique.</li></ul></p>"},{"i":"0278f93dca43","n":83,"o":"83-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une kératite","q":"Quels sont les drapeaux rouges à connaître concernant le diagnostic des kératites ?","a":"<ul><li>Un <strong>ulcère dendritique</strong> doit être considéré comme une kératite herpétique jusqu'à preuve du contraire, avec une <strong>contre-indication absolue aux corticoïdes locaux</strong> en raison du risque de perforation cornéenne.</li><li>Toute kératite chez un <strong>porteur de lentilles de contact</strong> doit faire suspecter une infection à <strong><em>Pseudomonas aeruginosa</em> (pyocyanique)</strong> ou à <strong><em>Acanthamoeba</em></strong>.</li></ul>"},{"i":"38377e6d0233","n":83,"o":"83-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une kératite","q":"Quels sont les principaux diagnostics différentiels à évoquer en fonction des aspects à la fluorescéine pour une kératite ?","a":"<p>Les principaux tableaux à comparer sont :</p><ul><li><strong>Kératite Ponctuée Superficielle (KPS)</strong>: douleur modérée, BAV modérée, œil rouge sans opacification, fluorescéine punctiforme superficielle. Étiologies : sécheresse, adénovirus, exposition, allergie, herpès.</li><li><strong>Ulcère de cornée</strong>: douleur et BAV possibles si atteinte de l'axe visuel, œil rouge, fluorescéine en plage bien limitée. Étiologies : traumatisme, HSV (dendritique), CE (linéaire), sécheresse, exposition.</li><li><strong>Abcès de cornée</strong>: douleur majeure, BAV possibles si axe visuel, œil rouge avec opacification blanchâtre mal limitée (infiltration stromale), fluorescéine au foyer d'infiltration. Étiologies : surinfection bactérienne (<strong>pyocyanique +++</strong>, staphylocoque, streptocoque), fongique, amibienne.</li></ul>"},{"i":"643ef331a55c","n":83,"o":"83-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une kératite","q":"Quels signes cliniques et paracliniques doivent faire suspecter une kératite ?","a":"<ul><li><strong>Signes cliniques</strong>:<ul><li><strong>BAV</strong> (variable selon l'atteinte)</li><li><strong>Douleur superficielle intense</strong> (sensation de corps étranger)</li><li>Larmoiement réflexe</li><li>Photophobie</li><li>Blépharospasme</li></ul></li><li><strong>Signes paracliniques (à la LAF après instillation de fluorescéine)</strong>:<ul><li><strong>Érosions/ulcérations de la cornée</strong> visiblement rehaussées par la fluorescéine</li><li>Opacification cornéenne en regard de l'ulcération</li><li>Cercle périkératique</li><li>Possibilité de réaction inflammatoire en chambre antérieure en cas de sévérité</li></ul></li></ul>"},{"i":"906cb3400baa","n":83,"o":"83-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une kératite","q":"Comment définir une kératite sur le plan physiopathologique et clinique ?","a":"<p>Une kératite est une atteinte de la cornée (épithéliale, ulcérative ou stromale infiltrative), aiguë ou chronique, se manifestant cliniquement par un <strong>œil rouge douloureux avec une baisse d'acuité visuelle (BAV)</strong>.</p>"},{"i":"be331a62ad28","n":83,"o":"83-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une kératite","q":"Quels sont les aspects spécifiques de la fluorescéine permettant d'orienter le diagnostic étiologique d'une kératite ?","a":"<ul><li><strong>Ulcération unique régulière</strong>: oriente vers un traumatisme.</li><li><strong>Ulcération localisée + zone blanche adjacente</strong>: oriente vers un abcès de cornée (bactérien, fongique) ou une infiltration inflammatoire stérile.</li><li><strong>Ulcère dendritique en « feuille de fougère »</strong>: signe pathognomonique de la <strong>kératite herpétique</strong>.</li><li><strong>Kératite ponctuée superficielle (KPS)</strong>: oriente vers un syndrome sec, une kérato-conjonctivite à adénovirus ou une kératite zostérienne.</li><li><strong>Lésions linéaires</strong>: oriente vers un corps étranger sous la paupière supérieure.</li><li><strong>Signe de Seidel</strong> (lavage de la fluorescéine par l'humeur aqueuse): signe une <strong>plaie cornéenne pénétrante</strong> avec sortie d'humeur aqueuse.</li></ul>"},{"i":"f9b53cff1fcb","n":83,"o":"83-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une kératite","q":"Quels sont les examens complémentaires indispensables pour établir le diagnostic positif d'une kératite ?","a":"<p>Le diagnostic positif d'une kératite repose sur l'examen à la <strong>lampe à fente (LAF)</strong>, complété par le <strong>test à la fluorescéine</strong>.</p>"},{"i":"41994964aaed","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Comment se présente cliniquement et diagnostiquement une uvéite intermédiaire ?","a":"<p>L'uvéite intermédiaire se présente avec :</p><ul><li>Une baisse d'acuité visuelle (BAV) non brutale, progressive sur plusieurs jours.</li><li>Un <strong>œil blanc</strong> et <strong>indolore</strong>.</li><li>Des <strong>myodésopsies</strong> (corps flottants).</li></ul><p>À l'examen, le fond d'œil (FO) est souvent mal visible, mais la lampe à fente (LAF) révèle un <strong>trouble du vitré avec des cellules inflammatoires (hyalite)</strong>.</p>"},{"i":"50b88e42a83b","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Quelle est la définition d'une uvéite et comment est-elle classée selon sa topographie ?","a":"<p>L'uvéite est une <strong>inflammation de l'uvée</strong>, qui comprend l'iris, le corps ciliaire et la choroïde.<br>Elle est classée selon sa topographie en :</p><ul><li><strong>Uvéite antérieure</strong> (iridocyclite) : la plus fréquente, concernant l'iris et le corps ciliaire.</li><li><strong>Uvéite intermédiaire</strong> : l'inflammation est principalement localisée dans le vitré.</li><li><strong>Uvéite postérieure</strong> : atteinte de la choroïde et/ou de la rétine.</li><li><strong>Panuvéite</strong> : inflammation de toutes les structures de l'uvée (tout l'œil).</li></ul>"},{"i":"514217621d87","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Pourquoi une enquête étiologique est-elle essentielle en cas d'uvéite antérieure, et quelles en sont les étapes minimales ?","a":"<p>Une enquête étiologique est essentielle car l'uvéite antérieure est souvent la manifestation oculaire d'une <strong>maladie systémique sous-jacente</strong>, même si elle reste négative dans un tiers à la moitié des cas.<br>Le bilan étiologique minimal comprend la recherche de :</p><ul><li><strong>Inflammation générale</strong> : NFS-plaquettes, CRP, VS, EPP.</li><li><strong>Spondylarthrite (SpA)</strong> : Ag HLA-B27, Rx rachis/bassin.</li><li><strong>Tuberculose ou sarcoïdose</strong> : RXT, IDR.</li><li><strong>Sarcoïdose spécifique</strong> : Enzyme de conversion de l'angiotensine (ECA), bilan phosphocalcique, ionogramme/urée/créatinine.</li><li><strong>Syphilis</strong> : TPHA-VDRL.</li></ul>"},{"i":"83bb499df199","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Quels sont les signes cliniques caractéristiques d'une uvéite antérieure (iridocyclite) lors de l'examen ophtalmologique ?","a":"<p>Lors de l'examen ophtalmologique, une uvéite antérieure se manifeste par :</p><ul><li>Un <strong>œil rouge</strong> et des douleurs profondes modérées sus-orbitaires.</li><li>Une baisse d'acuité visuelle (BAV) variable.</li><li>Un <strong>myosis relatif</strong> de la pupille.</li><li>Une <strong>injection ciliaire périkératique</strong>.</li><li>Des <strong>synéchies postérieures</strong> (adhérences irido-cristalliniennes déformant la pupille à la dilatation).</li><li>Un <strong>Tyndall</strong> (visibilité de protéines et cellules inflammatoires dans l'humeur aqueuse, appelé « phare dans le brouillard »).</li><li>Des <strong>précipités rétrocornéens</strong> (fins ou granulomateux « en graisse de mouton »).</li></ul>"},{"i":"91e67d9abd28","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Quelles sont les étiologies principales d'une uvéite antérieure à hypopion ?","a":"<p>Les <strong>trois causes principales</strong> d'une uvéite antérieure avec hypopion sont :</p><ul><li>La <strong>spondylarthrite (SpA) HLA-B27 +</strong>.</li><li>La <strong>maladie de Behçet</strong>.</li><li>L'<strong>endophtalmie postopératoire</strong>.</li></ul>"},{"i":"951d5e8aecab","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Quelles sont les caractéristiques cliniques et les étiologies à rechercher en cas de précipités rétrocornéens granulomateux (\"en graisse de mouton\") dans une uvéite antérieure ?","a":"<p>Des précipités rétrocornéens <strong>granulomateux</strong> (« en graisse de mouton ») orientent vers des étiologies spécifiques, notamment :</p><ul><li>La <strong>sarcoïdose</strong>.</li><li>La <strong>tuberculose</strong>.</li><li>La <strong>sclérose en plaques (SEP)</strong>.</li><li>La <strong>syphilis</strong>.</li><li>L'<strong>herpès</strong>.</li></ul>"},{"i":"b9f1ac844401","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Quelles sont les étiologies les plus fréquentes d'uvéites postérieures, en distinguant les causes infectieuses et systémiques ?","a":"<p>Les étiologies des uvéites postérieures incluent :</p><ul><li><strong>Causes infectieuses</strong> :</li><ul><li><strong>Toxoplasmose</strong> (uvéite infectieuse la plus fréquente, chorio-rétinite toxoplasmique).</li><li>HSV, VZV.</li><li>CMV (chez l'immunodéprimé).</li><li>Syphilis, bartonellose, tuberculose.</li></ul><li><strong>Causes systémiques</strong> :</li><ul><li><strong>Sarcoïdose</strong> (très fréquente).</li><li><strong>Maladie de Behçet</strong> (avec un risque fonctionnel élevé).</li></ul></ul>"},{"i":"ea9e8469ffae","n":83,"o":"83-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une uvéite (uvéite antérieure, postérieure ou panuvéite)","q":"Quels sont les signes cliniques et les risques associés à une uvéite postérieure, et comment est réalisé le diagnostic ?","a":"<p>Les signes cliniques d'une uvéite postérieure sont :</p><ul><li>Des <strong>myodésopsies</strong>.</li><li>Une baisse d'acuité visuelle (BAV) si atteinte maculaire, du nerf optique ou hyalite associée.</li><li>L'œil peut être d'aspect externe normal ou présenter un œil rouge avec douleurs ciliaires (en cas d'HSV/VZV).</li></ul><p>Le diagnostic est confirmé par un <strong>fond d'œil systématique après dilatation</strong>, qui révèle une atteinte de la choroïde et/ou de la rétine, souvent associée à une hyalite.<br>Les risques incluent une <strong>atteinte maculaire, vasculaire ou papillaire irrémédiable</strong>, ainsi que des complications rétiniennes telles que l'œdème maculaire cystoïde et le décollement de rétine tractionnel.</p>"}]};